/**
 * Offscreen document: the only place audio is touched, and the source of truth for the
 * session (the MV3 service worker may be suspended at any time; this page is not).
 *
 * tab audio (tabCapture stream id) → getUserMedia → TranscriptionSession (@heard/shared)
 * → TranscriptEvents broadcast to the background (relays to the overlay) and to the
 * popup / side panel. Transcripts live in memory only.
 */
import { browser } from "wxt/browser";
import {
  createTokenFetcher,
  initialTranscriptState,
  reduceTranscript,
  TranscriptionSession,
  type DeepgramCredential,
} from "@heard/shared";
import {
  broadcast,
  errorMessage,
  isRuntimeMessage,
  unknownError,
  type CommandResult,
  type OffscreenRequest,
  type OffscreenResponses,
  type SessionSnapshot,
} from "@/utils/messages";

let session: TranscriptionSession | null = null;
let transcript = initialTranscriptState();
let meta: Pick<SessionSnapshot, "tabId" | "tabTitle" | "overlayHidden"> = { tabId: null, tabTitle: null, overlayHidden: false };

function snapshot(): SessionSnapshot {
  return { ...meta, transcript };
}

function setMeta(next: Partial<typeof meta>) {
  meta = { ...meta, ...next };
  broadcast({ to: "broadcast", type: "meta", meta });
}

function userKeyCredential(key: string): () => Promise<DeepgramCredential> {
  const credential: DeepgramCredential = { type: "token", value: key };
  return async () => credential;
}

async function start(msg: Extract<OffscreenRequest, { type: "start" }>): Promise<CommandResult> {
  await stop();

  let stream: MediaStream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({
      audio: { mandatory: { chromeMediaSource: "tab", chromeMediaSourceId: msg.streamId } },
      video: false,
    } as unknown as MediaStreamConstraints);
  } catch (err) {
    return { ok: false, error: { code: "tab_audio_failed", detail: errorMessage(err) } };
  }

  const tabId = msg.tabId;
  setMeta({ tabId, tabTitle: msg.tabTitle, overlayHidden: false });
  const s = new TranscriptionSession({
    // A user key is used directly (Deepgram's `token` subprotocol); no Heard server involved.
    // Otherwise each (re)connect fetches a short-lived JWT from the Heard server.
    getToken:
      msg.credential.kind === "user-key"
        ? userKeyCredential(msg.credential.userKey)
        : createTokenFetcher(msg.credential.tokenEndpoint),
    workletUrl: browser.runtime.getURL("/pcm-worklet.js"),
    // chrome.tabCapture mutes the tab for the user; route the audio back to the speakers.
    preservePlayback: true,
    onEvent: (event) => {
      transcript = reduceTranscript(transcript, event);
      broadcast({ to: "broadcast", type: "transcript-event", tabId, event });
    },
  });
  // Only the spoken language matters here. Chrome's translator refuses to run in this hidden
  // page, so the side panel translates (see useSession in components/hooks.ts).
  s.setLanguages(msg.languages.spoken, "");
  session = s;
  // start() resolves after the first connect attempt; failures surface as status events.
  void s.start(stream);
  return { ok: true };
}

async function stop(): Promise<CommandResult> {
  const s = session;
  session = null;
  if (s) await s.stop();
  return { ok: true };
}

browser.runtime.onMessage.addListener((msg: unknown, _sender, sendResponse) => {
  if (!isRuntimeMessage(msg) || msg.to !== "offscreen") return;
  const reply = <K extends OffscreenRequest["type"]>(_type: K, value: OffscreenResponses[K] | Promise<OffscreenResponses[K]>) => {
    Promise.resolve(value).then(sendResponse, (err) => sendResponse(unknownError(err)));
    return true as const;
  };
  switch (msg.type) {
    case "start":
      return reply("start", start(msg));
    case "stop":
      return reply("stop", stop());
    case "get-state":
      return reply("get-state", snapshot());
    case "set-languages":
      session?.setLanguages(msg.languages.spoken, "");
      return reply("set-languages", { ok: true });
    case "set-overlay-hidden":
      setMeta({ overlayHidden: msg.hidden });
      return reply("set-overlay-hidden", { ok: true });
  }
});
/**
 * The extension's whole message protocol, in one place.
 *
 * Contexts:
 * - background (service worker): orchestrates capture, owns no transcript state.
 * - offscreen document: runs the TranscriptionSession; SOURCE OF TRUTH for session state.
 * - popup / side panel: UI; read state with `get-state`, then follow broadcasts.
 * - overlay content script: caption box inside the captured tab.
 *
 * `runtime.sendMessage` reaches every extension page at once, so every runtime message
 * carries a `to` field and each context ignores messages that aren't addressed to it.
 */
import { browser } from "wxt/browser";
import type { CaptionState, TranscriptEvent, TranscriptionStatus, TranscriptState } from "@heard/shared";
import type { ExtensionMessages } from "@/i18n/en";

/** Everything the UI needs to render one capture session. Lives in the offscreen document. */
export interface SessionSnapshot {
  /** Tab being (or last) captured; null when nothing has been captured. */
  tabId: number | null;
  tabTitle: string | null;
  /** The user dismissed the in-page caption box for this capture. */
  overlayHidden: boolean;
  transcript: TranscriptState;
}

export type SessionMeta = Pick<SessionSnapshot, "tabId" | "tabTitle" | "overlayHidden">;

/**
 * Why a command failed. Contexts send codes, not sentences, so each page can say it in its
 * own interface language (see `describeError`). `detail` fills the message's blank: a server
 * URL or Chrome's own error text.
 */
export type ErrorCode = keyof ExtensionMessages["errors"];
export interface CommandError {
  code: ErrorCode;
  detail?: string;
}

/** Generic reply for commands. */
export type CommandResult = { ok: true } | { ok: false; error: CommandError };

export function describeError(t: ExtensionMessages, error: CommandError): string {
  const m = t.errors[error.code] as string | ((detail: string) => string) | undefined;
  if (typeof m === "function") return m(error.detail ?? "");
  return m ?? t.errors.unknown(error.detail ?? "");
}

/** Failures that adding the user's own Deepgram key fixes. */
export function isNeedsKey(error: CommandError | null | undefined): boolean {
  return error?.code === "needs_key_unreachable" || error?.code === "needs_key_no_server_key";
}

/**
 * How the offscreen document authenticates to Deepgram. Chosen by the background, which
 * is the only context that reads the user's key from storage. Sent only background → offscreen.
 */
export type CredentialSource = { kind: "user-key"; userKey: string } | { kind: "server"; tokenEndpoint: string };

/* ----------------------------- → background ----------------------------- */

export type BackgroundRequest =
  | { to: "background"; type: "start"; tabId: number }
  | { to: "background"; type: "stop" }
  | { to: "background"; type: "get-state" }
  /** Re-show (injecting if necessary) the caption box in the captured tab. */
  | { to: "background"; type: "show-overlay" }
  /** From the overlay: the user closed the caption box. */
  | { to: "background"; type: "overlay-dismissed" }
  /** From a freshly injected overlay: "what should I show?" (tab comes from sender). */
  | { to: "background"; type: "overlay-hello" }
  /** From the side panel, which translates: a caption translation for the captured tab's overlay. */
  | { to: "background"; type: "overlay-translation"; event: TranslationEvent };

/** Translation events the side panel produces and the overlay shows. */
export type TranslationEvent = Extract<TranscriptEvent, { type: "caption-translated" | "translation-config" }>;

export interface BackgroundResponses {
  start: CommandResult;
  stop: CommandResult;
  "get-state": SessionSnapshot;
  "show-overlay": CommandResult;
  "overlay-dismissed": CommandResult;
  "overlay-hello": OverlayHello;
  "overlay-translation": CommandResult;
}

export interface OverlayHello {
  /** False when this tab is not the captured tab: the overlay should remove itself. */
  captured: boolean;
  hidden: boolean;
  status: TranscriptionStatus;
  caption: CaptionState | null;
  /** Translation of `caption` when captions are translated. */
  captionTranslation: string | null;
}

/** Spoken language (Deepgram code or "multi") and caption language ("" = as spoken). */
export interface SessionLanguages {
  spoken: string;
  caption: string;
}

/* ----------------------------- → offscreen ----------------------------- */

export type OffscreenRequest =
  | {
      to: "offscreen";
      type: "start";
      streamId: string;
      tabId: number;
      tabTitle: string | null;
      credential: CredentialSource;
      languages: SessionLanguages;
    }
  | { to: "offscreen"; type: "set-languages"; languages: SessionLanguages }
  | { to: "offscreen"; type: "stop" }
  | { to: "offscreen"; type: "get-state" }
  | { to: "offscreen"; type: "set-overlay-hidden"; hidden: boolean };

export interface OffscreenResponses {
  start: CommandResult;
  stop: CommandResult;
  "get-state": SessionSnapshot;
  "set-overlay-hidden": CommandResult;
  "set-languages": CommandResult;
}

/* --------------------------- offscreen → everyone --------------------------- */

export type Broadcast =
  | { to: "broadcast"; type: "transcript-event"; tabId: number | null; event: TranscriptEvent }
  | { to: "broadcast"; type: "meta"; meta: SessionMeta };

/* ----------------------- background → overlay (tabs.sendMessage) ----------------------- */

export type OverlayMessage =
  | { to: "overlay"; type: "event"; event: TranscriptEvent }
  | { to: "overlay"; type: "show" }
  /** Capture ended for this tab: remove the overlay entirely. */
  | { to: "overlay"; type: "teardown" };

export type RuntimeMessage = BackgroundRequest | OffscreenRequest | Broadcast;

/* ----------------------------- typed helpers ----------------------------- */

export function sendToBackground<T extends BackgroundRequest>(msg: T): Promise<BackgroundResponses[T["type"]]> {
  return browser.runtime.sendMessage(msg);
}

export function sendToOffscreen<T extends OffscreenRequest>(msg: T): Promise<OffscreenResponses[T["type"]]> {
  return browser.runtime.sendMessage(msg);
}

/** Fire-and-forget broadcast; "no receiver" errors are expected when no UI is open. */
export function broadcast(msg: Broadcast): void {
  browser.runtime.sendMessage(msg).catch(() => undefined);
}

export function sendToOverlay(tabId: number, msg: OverlayMessage): Promise<unknown> {
  return browser.tabs.sendMessage(tabId, msg);
}

export function isRuntimeMessage(msg: unknown): msg is RuntimeMessage {
  return typeof msg === "object" && msg !== null && "to" in msg && "type" in msg;
}

export function isOverlayMessage(msg: unknown): msg is OverlayMessage {
  return typeof msg === "object" && msg !== null && (msg as { to?: unknown }).to === "overlay";
}

/** Statuses during which audio is being captured. */
export function isCapturing(status: TranscriptionStatus): boolean {
  return status === "connecting" || status === "live" || status === "paused" || status === "reconnecting";
}

/**
 * Session errors that the user's (or the server's) Deepgram key can fix. These come from the
 * shared transcription code, which reports English sentences, hence the text match.
 */
export function isKeyError(message: string | null | undefined): boolean {
  return Boolean(message && /API key|Deepgram key/i.test(message));
}

export function errorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

export function unknownError(err: unknown): { ok: false; error: CommandError } {
  return { ok: false, error: { code: "unknown", detail: errorMessage(err) } };
}
/**
 * Background service worker: orchestrates a single capture at a time.
 *
 * It keeps NO session state of its own — MV3 may suspend it at any moment. Whenever it
 * needs to know what's going on it asks the offscreen document (`get-state`), which is
 * the source of truth. Transcript events carry their tabId, so relaying them to the
 * captured tab's overlay needs no memory either.
 */
import { browser, type Browser } from "wxt/browser";
import { defineBackground } from "wxt/utils/define-background";
import { initialTranscriptState, type TranscriptEvent } from "@heard/shared";
import { getCaptionSettings, getServerUrl, getUserKey, probeServer, restrictedReason, STORAGE_KEYS, tokenEndpoint } from "@/utils/config";
import { createCommandQueue } from "@/utils/command-queue";
import { getMessages, onUiLanguageChange } from "@/utils/i18n";
import {
  errorMessage,
  isCapturing,
  isRuntimeMessage,
  sendToOffscreen,
  sendToOverlay,
  unknownError,
  type BackgroundRequest,
  type BackgroundResponses,
  type CommandError,
  type CommandResult,
  type CredentialSource,
  type OverlayHello,
  type SessionLanguages,
  type SessionSnapshot,
} from "@/utils/messages";

const OFFSCREEN_PATH = "/offscreen.html";
const OVERLAY_SCRIPT = "/content-scripts/overlay.js";
const LIVE_COLOR = "#e5484d";

export default defineBackground(() => {
  const enqueueCaptureCommand = createCommandQueue();
  /* ------------------------------ offscreen ------------------------------ */

  let creatingOffscreen: Promise<void> | null = null;

  async function hasOffscreen(): Promise<boolean> {
    const contexts = await browser.runtime.getContexts({
      contextTypes: ["OFFSCREEN_DOCUMENT" as Browser.runtime.ContextType],
      documentUrls: [browser.runtime.getURL(OFFSCREEN_PATH)],
    });
    return contexts.length > 0;
  }

  async function ensureOffscreen(): Promise<void> {
    if (await hasOffscreen()) return;
    creatingOffscreen ??= browser.offscreen
      .createDocument({
        url: OFFSCREEN_PATH,
        reasons: ["USER_MEDIA" as Browser.offscreen.Reason],
        justification: "Capture the audio of the tab the user chose and stream it to Deepgram for live captions.",
      })
      .finally(() => {
        creatingOffscreen = null;
      });
    await creatingOffscreen;
  }

  async function closeOffscreen(): Promise<void> {
    if (await hasOffscreen()) await browser.offscreen.closeDocument().catch(() => undefined);
  }

  /** Re-learn the session from the offscreen document (survives service worker restarts). */
  async function getSnapshot(): Promise<SessionSnapshot> {
    if (creatingOffscreen) await creatingOffscreen.catch(() => undefined);
    if (await hasOffscreen()) {
      try {
        const snap = await sendToOffscreen({ to: "offscreen", type: "get-state" });
        if (snap) return snap;
      } catch {
        /* document is closing */
      }
    }
    return { tabId: null, tabTitle: null, overlayHidden: false, transcript: initialTranscriptState() };
  }

  /* ------------------------------ indicators ------------------------------ */

  async function setLiveBadge(tabId: number, live: boolean) {
    try {
      await browser.action.setBadgeText({ tabId, text: live ? "LIVE" : "" });
      if (live) {
        await browser.action.setBadgeBackgroundColor({ tabId, color: LIVE_COLOR });
        await browser.action.setBadgeTextColor?.({ tabId, color: "#ffffff" });
      }
      const t = await getMessages();
      await browser.action.setTitle({ tabId, title: live ? t.action.live : t.action.idle });
    } catch {
      /* tab is gone */
    }
  }

  async function injectOverlay(tabId: number): Promise<boolean> {
    try {
      await browser.scripting.executeScript({ target: { tabId }, files: [OVERLAY_SCRIPT] });
      return true;
    } catch {
      // chrome:// pages, the Web Store, PDFs, or activeTab no longer granted after navigation.
      return false;
    }
  }

  /* ------------------------------ commands ------------------------------ */

  function explainCaptureError(err: unknown): CommandError {
    const msg = errorMessage(err);
    if (/invoked|activeTab/i.test(msg)) return { code: "capture_not_invoked" };
    if (/active stream/i.test(msg)) return { code: "capture_busy" };
    if (/chrome pages|cannot be captured/i.test(msg)) return { code: "capture_blocked" };
    return { code: "capture_failed", detail: msg };
  }

  /**
   * The user's own key wins; otherwise the Heard server mints tokens. Without a key we
   * check the server first so a missing/keyless server is explained up front instead of
   * surfacing later as a network error. The key itself only travels background → offscreen.
   */
  async function resolveCredential(): Promise<{ ok: true; credential: CredentialSource } | Extract<CommandResult, { ok: false }>> {
    const userKey = await getUserKey();
    if (userKey) return { ok: true, credential: { kind: "user-key", userKey } };
    const serverUrl = await getServerUrl();
    const status = await probeServer(serverUrl);
    if (status === "unreachable") return { ok: false, error: { code: "needs_key_unreachable", detail: serverUrl } };
    if (status === "no_server_key") return { ok: false, error: { code: "needs_key_no_server_key", detail: serverUrl } };
    return { ok: true, credential: { kind: "server", tokenEndpoint: tokenEndpoint(serverUrl) } };
  }

  async function start(tabId: number): Promise<CommandResult> {
    const tab = await browser.tabs.get(tabId).catch(() => null);
    if (!tab) return { ok: false, error: { code: "tab_gone" } };
    const restricted = restrictedReason(tab.url);
    if (restricted) return { ok: false, error: { code: restricted } };

    const cred = await resolveCredential();
    if (!cred.ok) return cred;

    // One capture at a time: stop whatever is running (on this or another tab) first.
    const current = await getSnapshot();
    if (current.tabId !== null && isCapturing(current.transcript.status)) await stop();

    let streamId: string;
    try {
      streamId = await browser.tabCapture.getMediaStreamId({ targetTabId: tabId });
    } catch (err) {
      return { ok: false, error: explainCaptureError(err) };
    }

    try {
      await ensureOffscreen();
      const res = await sendToOffscreen({
        to: "offscreen",
        type: "start",
        streamId,
        tabId,
        tabTitle: tab.title ?? null,
        credential: cred.credential,
        languages: await currentLanguages(),
      });
      if (!res?.ok) {
        await closeOffscreen();
        return res ?? { ok: false, error: { code: "offscreen_silent" } };
      }
    } catch (err) {
      await closeOffscreen();
      return { ok: false, error: { code: "start_failed", detail: errorMessage(err) } };
    }

    await setLiveBadge(tabId, true);
    void injectOverlay(tabId);
    return { ok: true };
  }

  async function stop(): Promise<CommandResult> {
    const snap = await getSnapshot();
    if (await hasOffscreen()) {
      // session.stop() flushes final words and closes socket + audio before replying.
      await sendToOffscreen({ to: "offscreen", type: "stop" }).catch(() => undefined);
      await closeOffscreen();
    }
    if (snap.tabId !== null) {
      await setLiveBadge(snap.tabId, false);
      sendToOverlay(snap.tabId, { to: "overlay", type: "teardown" }).catch(() => undefined);
    }
    return { ok: true };
  }

  async function showOverlay(): Promise<CommandResult> {
    const snap = await getSnapshot();
    if (snap.tabId === null || !isCapturing(snap.transcript.status)) {
      return { ok: false, error: { code: "not_running" } };
    }
    await sendToOffscreen({ to: "offscreen", type: "set-overlay-hidden", hidden: false });
    try {
      await sendToOverlay(snap.tabId, { to: "overlay", type: "show" });
      return { ok: true };
    } catch {
      return (await injectOverlay(snap.tabId))
        ? { ok: true }
        : { ok: false, error: { code: "overlay_blocked" } };
    }
  }

  async function currentLanguages(): Promise<SessionLanguages> {
    const s = await getCaptionSettings();
    return { spoken: s.spokenLanguage, caption: s.captionLanguage };
  }

  async function overlayHello(tabId: number | undefined): Promise<OverlayHello> {
    const snap = await getSnapshot();
    const captured = tabId !== undefined && snap.tabId === tabId && isCapturing(snap.transcript.status);
    return {
      captured,
      hidden: snap.overlayHidden,
      status: snap.transcript.status,
      caption: captured ? snap.transcript.caption : null,
      captionTranslation: captured && snap.transcript.translation?.target ? snap.transcript.translation.caption : null,
    };
  }

  /* ------------------------------ relaying ------------------------------ */

  function relay(tabId: number | null, event: TranscriptEvent) {
    if (tabId === null) return;
    if (event.type === "status") {
      const live = isCapturing(event.status);
      void setLiveBadge(tabId, live);
      if (!live) sendToOverlay(tabId, { to: "overlay", type: "teardown" }).catch(() => undefined);
    }
    // The overlay only renders the caption + status; transcript lines stay in the panels.
    if (
      event.type === "caption" ||
      event.type === "status" ||
      event.type === "reset" ||
      event.type === "caption-translated" ||
      event.type === "translation-config"
    ) {
      sendToOverlay(tabId, { to: "overlay", type: "event", event }).catch(() => undefined);
    }
  }

  /* ------------------------------ listeners ------------------------------ */

  browser.runtime.onMessage.addListener((msg: unknown, sender, sendResponse) => {
    if (!isRuntimeMessage(msg)) return;
    if (msg.to === "broadcast") {
      if (msg.type === "transcript-event") relay(msg.tabId, msg.event);
      return;
    }
    if (msg.to !== "background") return;

    const reply = <K extends BackgroundRequest["type"]>(_type: K, value: Promise<BackgroundResponses[K]>) => {
      value.then(sendResponse, (err) => sendResponse(unknownError(err)));
      return true as const;
    };
    switch (msg.type) {
      case "start":
        return reply("start", enqueueCaptureCommand(() => start(msg.tabId)));
      case "stop":
        return reply("stop", enqueueCaptureCommand(stop));
      case "get-state":
        return reply("get-state", getSnapshot());
      case "show-overlay":
        return reply("show-overlay", enqueueCaptureCommand(showOverlay));
      case "overlay-dismissed":
        return reply(
          "overlay-dismissed",
          getSnapshot().then(async (snap) => {
            if (snap.tabId === sender.tab?.id && (await hasOffscreen())) {
              await sendToOffscreen({ to: "offscreen", type: "set-overlay-hidden", hidden: true });
            }
            return { ok: true } as const;
          }),
        );
      case "overlay-hello":
        return reply("overlay-hello", overlayHello(sender.tab?.id));
      case "overlay-translation":
        return reply(
          "overlay-translation",
          getSnapshot().then((snap) => {
            if (snap.tabId !== null && isCapturing(snap.transcript.status)) {
              sendToOverlay(snap.tabId, { to: "overlay", type: "event", event: msg.event }).catch(() => undefined);
            }
            return { ok: true } as const;
          }),
        );
    }
  });

  // Language changes in the side panel apply to the running session.
  browser.storage.onChanged.addListener((changes, area) => {
    if (area !== "local" || !(STORAGE_KEYS.captionSettings in changes)) return;
    void (async () => {
      if (!(await hasOffscreen())) return;
      await sendToOffscreen({ to: "offscreen", type: "set-languages", languages: await currentLanguages() }).catch(() => undefined);
    })();
  });

  // A new interface language retitles the toolbar icon of a running capture.
  onUiLanguageChange(() => {
    void getSnapshot().then((snap) => {
      if (snap.tabId !== null && isCapturing(snap.transcript.status)) void setLiveBadge(snap.tabId, true);
    });
  });

  browser.tabs.onRemoved.addListener((tabId) => {
    void enqueueCaptureCommand(async () => {
      const snap = await getSnapshot();
      if (snap.tabId === tabId && isCapturing(snap.transcript.status)) await stop();
    });
  });

  // After a full navigation the overlay is gone (and Chrome resets per-tab badges).
  // tabCapture keeps streaming across navigations, so restore both when allowed.
  browser.tabs.onUpdated.addListener((tabId, info) => {
    if (info.status !== "complete") return;
    void getSnapshot().then(async (snap) => {
      if (snap.tabId !== tabId || !isCapturing(snap.transcript.status)) return;
      await setLiveBadge(tabId, true);
      if (!snap.overlayHidden) await injectOverlay(tabId);
    });
  });
});
import { browser } from "wxt/browser";
import { normalizeCaptionSettings, type CaptionSettings } from "@heard/shared";
import { normalizeServerUrl } from "./server-url";

/** Build-time default (`WXT_HEARD_URL=https://heard.example npx wxt build`). */
export const DEFAULT_HEARD_URL: string = normalizeServerUrl(
  (import.meta.env.WXT_HEARD_URL as string | undefined) || "http://localhost:3100",
) ?? "http://localhost:3100";

/** chrome.storage.local keys. Transcripts are never stored. */
export const STORAGE_KEYS = {
  serverUrl: "serverUrl",
  captionSettings: "captionSettings",
  overlayLayout: "overlayLayout",
  /** The user's own Deepgram API key ("bring your own key"). Only ever sent to Deepgram. */
  deepgramKey: "deepgramKey",
  /** Interface language ("en", "es", …); missing means "follow Chrome". */
  uiLanguage: "uiLanguage",
} as const;

/** chrome.storage.session keys (cleared when the browser closes). */
export const SESSION_KEYS = {
  /** One-shot request from the popup: open the side panel on this view. */
  sidepanelView: "sidepanelView",
} as const;

/** Popup → side panel: "show this view". Scoped to a window; expires instead of being consumed. */
export interface SidepanelViewRequest {
  view: "settings";
  windowId: number;
  at: number;
}

export const SIDEPANEL_VIEW_REQUEST_TTL_MS = 10_000;

/** Caption box placement, as fractions of the viewport so it survives resizes / fullscreen. */
export interface OverlayLayout {
  /** Left edge, 0..1 of viewport width. */
  x: number;
  /** Top edge, 0..1 of viewport height. */
  y: number;
  /** Box width in CSS px. */
  width: number;
  /** The user placed the box themselves; otherwise it sits on the page's main video. */
  manual?: boolean;
}

export async function getServerUrl(): Promise<string> {
  const stored = (await browser.storage.local.get(STORAGE_KEYS.serverUrl))[STORAGE_KEYS.serverUrl];
  return (typeof stored === "string" && normalizeServerUrl(stored)) || DEFAULT_HEARD_URL;
}

export function tokenEndpoint(serverUrl: string): string {
  return `${serverUrl}/api/deepgram/token`;
}

/** The user's saved Deepgram key, or null. Never log or broadcast the returned value. */
export async function getUserKey(): Promise<string | null> {
  const stored = (await browser.storage.local.get(STORAGE_KEYS.deepgramKey))[STORAGE_KEYS.deepgramKey];
  return typeof stored === "string" && stored.trim() ? stored.trim() : null;
}

/** "••••abcd" — the only form of the key the UI ever shows. */
export function maskKey(key: string): string {
  return `••••${key.slice(-4)}`;
}

/**
 * What the Heard server can do for us when the user has no key of their own.
 * - ready: reachable and has a Deepgram key.
 * - no_server_key: reachable but can't mint tokens.
 * - unknown: reachable, but it doesn't report whether it has a key (older server).
 * - unreachable: nothing answered.
 */
export type ServerStatus = "ready" | "no_server_key" | "unknown" | "unreachable";

/** `GET {server}/api/deepgram/token` → `{ serverKey: boolean }`. Works from pages and the service worker. */
export async function probeServer(serverUrl: string, timeoutMs = 3000): Promise<ServerStatus> {
  const url = tokenEndpoint(serverUrl);
  try {
    const res = await fetch(url, { method: "GET", cache: "no-store", signal: AbortSignal.timeout(timeoutMs) });
    const body = (await res.json().catch(() => null)) as { serverKey?: unknown; code?: unknown } | null;
    if (body && typeof body.serverKey === "boolean") return body.serverKey ? "ready" : "no_server_key";
    if (body?.code === "no_server_key") return "no_server_key";
    return "unknown";
  } catch {
    // A CORS-less answer (e.g. an older server without GET) still proves something is listening.
    try {
      await fetch(url, { method: "GET", mode: "no-cors", cache: "no-store", signal: AbortSignal.timeout(timeoutMs) });
      return "unknown";
    } catch {
      return "unreachable";
    }
  }
}

export async function getCaptionSettings(): Promise<CaptionSettings> {
  const stored = (await browser.storage.local.get(STORAGE_KEYS.captionSettings))[STORAGE_KEYS.captionSettings];
  return { ...normalizeCaptionSettings(stored), position: "overlay" };
}

/**
 * Pages Chrome never lets extensions capture or script. `url` is only known when we have
 * activeTab for the tab (popup) — undefined means "can't tell", so we let Chrome decide.
 */
export function restrictedReason(url: string | undefined): "restricted_chrome" | "restricted_webstore" | null {
  if (!url) return null;
  if (/^(chrome|edge|brave|about|devtools|view-source|chrome-extension|chrome-search|chrome-untrusted):/i.test(url)) {
    return "restricted_chrome";
  }
  if (/^https:\/\/(chromewebstore\.google\.com|chrome\.google\.com\/webstore)/i.test(url)) {
    return "restricted_webstore";
  }
  return null;
}

