1014	        if (!target) break;
1015	        const text = caption.text ? await this.translate(caption.text, caption.language) : "";
1016	        if (generation !== this.generation) continue;
1017	        // Untranslatable text shows as spoken rather than leaving an older translation up.
1018	        this.emit({ type: "caption-translated", target, text: text ?? caption.text });
1019	      }
1020	    } finally {
1021	      this.captionBusy = false;
1022	    }
1023	  }
1024	}
