1027	 * it only describes transcription state so any surface (web app, extension, future
1028	 * providers) can render it.
1029	 */
1030	
1031	export type TranscriptionStatus =
1032	  | "idle"
1033	  | "connecting"
1034	  | "live"
1035	  | "paused"
1036	  | "reconnecting"
1037	  | "error";
1038	
1039	/** A committed (final) transcript line. Times are seconds. */
1040	export interface TranscriptLine {
1041	  id: string;
1042	  text: string;
1043	  /** Seconds since transcription started, measured in audio actually streamed. */
1044	  start: number;
1045	  end: number;
1046	  /** Position in the media (e.g. video currentTime) when known; null for unseekable sources. */
1047	  mediaStart: number | null;
1048	  mediaEnd: number | null;
1049	  /** Wall-clock ms when the line was committed. */
1050	  createdAt: number;
1051	  /** Language Deepgram reported for most of the line's words (auto-detect only). */
1052	  language?: string;
1053	}
