1055	/** What should be on screen as a caption right now. */
1056	export interface CaptionState {
1057	  /** Finalized-but-uncommitted words followed by the current interim hypothesis. */
1058	  text: string;
1059	  /** True when the tail of `text` is still an interim (may change) result. */
1060	  hasInterim: boolean;
1061	  /** Wall-clock ms of the last change; renderers use it to fade stale captions. */
1062	  updatedAt: number;
