1071	  target: string;
1072	  /**
1073	   * `download`: the language pair needs a one-time download, which only a click can start.
1074	   * `failed`: Chrome has the translator but it errored or stopped answering; `detail` says why.
1075	   */
1076	  kind: "download" | "unsupported" | "no-api" | "failed";
