          </div>
          <TranscriptToolbar lines={ts.lines} query={query} onQueryChange={setQuery} fileName={fileName} className="px-3 py-3" labels={ui.toolbar} />
          <TranscriptView
            lines={ts.lines}
            caption={ts.caption}
            live={running}
            query={query}
            timeBase={timeBase}
            onSeek={timeBase === "media" ? onSeek : undefined}
