/**
 * Tab-audio capture for the web player. The user shares *this tab* (with its audio) via
 * Chrome's screen-share picker; we drop the video track immediately and keep only audio.
 */

export type CaptureSupport = { ok: true } | { ok: false; reason: string };

interface UAData {
  mobile?: boolean;
  brands?: Array<{ brand: string }>;
}

export function detectCaptureSupport(): CaptureSupport {
  if (typeof navigator === "undefined") return { ok: true };
  const ua = navigator.userAgent;
  const uaData = (navigator as Navigator & { userAgentData?: UAData }).userAgentData;
  const mobile = uaData?.mobile ?? /Android|iPhone|iPad|iPod|Mobile/i.test(ua);
  if (mobile) {
    return { ok: false, reason: "Live captions need tab-audio sharing, which phones and tablets don't support. Open Heard in Chrome or Edge on a computer." };
  }
  if (/Firefox\//.test(ua)) {
    return { ok: false, reason: "Firefox can't share a tab's audio with websites. Open Heard in Chrome or Edge on a computer." };
  }
  const chromium = uaData?.brands?.some((b) => /Chromium|Google Chrome|Microsoft Edge/i.test(b.brand)) ?? /Chrome\/|Edg\//.test(ua);
  if (!chromium) {
    return { ok: false, reason: "This browser can't share a tab's audio with websites. Open Heard in Chrome or Edge on a computer." };
  }
  if (!navigator.mediaDevices?.getDisplayMedia) {
    return { ok: false, reason: "Tab sharing is unavailable here. Make sure the page is served over HTTPS (or localhost) in Chrome or Edge." };
  }
  return { ok: true };
}

export class CaptureError extends Error {
  constructor(
    message: string,
    readonly kind: "cancelled" | "no-audio" | "failed",
  ) {
    super(message);
  }
}

/** Must be called from a click handler (user activation). Resolves with an audio-only stream. */
export async function captureTabAudio(): Promise<MediaStream> {
  let stream: MediaStream;
  try {
    stream = await navigator.mediaDevices.getDisplayMedia({
      video: true,
      audio: {
        echoCancellation: false,
        noiseSuppression: false,
        autoGainControl: false,
        suppressLocalAudioPlayback: false,
      },
      preferCurrentTab: true,
      selfBrowserSurface: "include",
      surfaceSwitching: "exclude",
      systemAudio: "exclude",
    } as DisplayMediaStreamOptions);
  } catch (err) {
    const name = (err as DOMException)?.name;
    if (name === "NotAllowedError" || name === "AbortError") {
      throw new CaptureError("Sharing was cancelled. Start again and pick “This tab” when Chrome asks.", "cancelled");
    }
    throw new CaptureError(`Chrome couldn't share this tab: ${(err as Error).message}`, "failed");
  }

  // We only need the sound — stop video right away so nothing is encoded.
  for (const t of stream.getVideoTracks()) {
    t.stop();
    stream.removeTrack(t);
  }
  if (stream.getAudioTracks().length === 0) {
    throw new CaptureError(
      "You didn't share tab audio. Start again and make sure “Also share tab audio” is switched on.",
      "no-audio",
    );
  }
  return stream;
}
/**
 * Caption overlay, injected at runtime (chrome.scripting) into the captured tab only.
 * No `matches` → no host permissions and nothing runs on pages the user didn't choose.
 *
 * Rendered in a shadow root so the site's CSS can't touch it (and vice versa). Styles are
 * hand-written (see ./style.ts) — Tailwind v4's @property-based utilities don't apply
 * inside shadow roots.
 */
import { createRoot, type Root } from "react-dom/client";
import { createShadowRootUi } from "wxt/utils/content-script-ui/shadow-root";
import { defineContentScript } from "wxt/utils/define-content-script";
import { browser } from "wxt/browser";
import { EMPTY_CAPTION } from "@heard/shared";
import { isOverlayMessage, sendToBackground } from "@/utils/messages";
import { Overlay, createOverlayStore } from "./Overlay";
import { OVERLAY_CSS } from "./style";

const GUARD = "__heardOverlayMounted";

export default defineContentScript({
  registration: "runtime",
  async main(ctx) {
    const w = window as unknown as Record<string, unknown>;
    if (w[GUARD]) return; // already injected into this document
    w[GUARD] = true;

    const hello = await sendToBackground({ to: "background", type: "overlay-hello" }).catch(() => null);
    if (!hello?.captured) {
      w[GUARD] = false;
      return;
    }

    const store = createOverlayStore({
      status: hello.status,
      caption: hello.caption ?? EMPTY_CAPTION,
      translation: hello.captionTranslation ?? null,
      hidden: hello.hidden,
    });

    const ui = await createShadowRootUi<Root>(ctx, {
      name: "heard-captions",
      position: "inline",
      anchor: () => document.fullscreenElement ?? document.body,
      append: "last",
      css: OVERLAY_CSS,
      onMount(container) {
        const root = createRoot(container);
        root.render(
          <Overlay
            store={store}
            onDismiss={() => {
              store.set({ hidden: true });
              void sendToBackground({ to: "background", type: "overlay-dismissed" }).catch(() => undefined);
            }}
          />,
        );
        return root;
      },
      onRemove(root) {
        root?.unmount();
      },
    });
    ui.mount();

    // Fullscreen video puts one element in the top layer; anything outside it is invisible.
    const onFullscreen = () => {
      const parent = document.fullscreenElement ?? document.body;
      if (ui.shadowHost.parentElement !== parent) parent.appendChild(ui.shadowHost);
    };
    document.addEventListener("fullscreenchange", onFullscreen);

    const onMessage = (msg: unknown) => {
      if (!isOverlayMessage(msg)) return;
      const m = msg;
      switch (m.type) {
        case "event": {
          const e = m.event;
          if (e.type === "caption") store.set({ caption: e.caption });
          else if (e.type === "status") store.set({ status: e.status });
          else if (e.type === "reset") store.set({ caption: EMPTY_CAPTION, translation: null });
          else if (e.type === "caption-translated") store.set({ translation: e.text });
          else if (e.type === "translation-config" && !e.target) store.set({ translation: null });
          break;
        }
        case "show":
          store.set({ hidden: false });
          break;
        case "teardown":
          teardown();
          break;
      }
    };
    browser.runtime.onMessage.addListener(onMessage);

    function teardown() {
      browser.runtime.onMessage.removeListener(onMessage);
      document.removeEventListener("fullscreenchange", onFullscreen);
      ui.remove();
      w[GUARD] = false;
    }
    // Extension reloaded/updated: this script is orphaned.
    ctx.onInvalidated(teardown);
  },
});
