/** Dubbing languages as `[translator code, English name]`, in caption-language order. */
export const DUB_LANGUAGES: ReadonlyArray<readonly [string, string]> = CAPTION_LANGUAGES.filter(([code]) => (DUB_VOICES[code]?.length ?? 0) > 0);

export function voicesFor(language: string): readonly FluxVoice[] {
  return DUB_VOICES[language] ?? [];
}

/** The voice if it belongs to the language, else that language's first voice. */
export function pickVoice(language: string, voice: string | null | undefined): string {
  const voices = voicesFor(language);
  return voices.find((x) => x.id === voice)?.id ?? voices[0]?.id ?? "";
}

export interface DubSettings {
  /** Translator code of the dubbed speech (a key of DUB_VOICES). */
  language: string;
  /** Flux TTS model id. */
  voice: string;
  /** Original audio level while dubbing, 0..1 (only where it can be controlled). */
  originalVolume: number;
  /** Dubbed speech level, 0..1. */
  dubVolume: number;
}

/** Original audio drops to 10% while dubbing so the interpreter is clearly on top. */
export const DEFAULT_DUB_SETTINGS: DubSettings = {
  language: "es",
  voice: "flux-carmen-es",
  originalVolume: 0.1,
  dubVolume: 1,
};

/** Merge untrusted stored settings with defaults. */
export function normalizeDubSettings(input: unknown): DubSettings {
  const s = { ...DEFAULT_DUB_SETTINGS, ...(typeof input === "object" && input !== null ? input : {}) } as DubSettings;
  const language = typeof s.language === "string" && voicesFor(s.language).length > 0 ? s.language : DEFAULT_DUB_SETTINGS.language;
  return {
    language,
    voice: pickVoice(language, typeof s.voice === "string" ? s.voice : null),
    originalVolume: unit(s.originalVolume, DEFAULT_DUB_SETTINGS.originalVolume),
    dubVolume: unit(s.dubVolume, DEFAULT_DUB_SETTINGS.dubVolume),
  };
}

function unit(n: unknown, fallback: number): number {
  const x = Number(n);
  return Number.isFinite(x) ? Math.min(1, Math.max(0, x)) : fallback;
}

/**
 * - `off`: dubbing is disabled.
 * - `connecting`: opening the Flux TTS socket.
 * - `listening`: ready, waiting for the next finished phrase.
 * - `translating`: a phrase is being translated.
 * - `playing`: dubbed speech is coming out of the speakers.
 * - `reconnecting`: the TTS socket dropped; retrying.
 * - `unavailable`: dubbing can't run (bad key, repeated failures, unsupported capture);
 *   original audio is restored and `error` says why.
 */
export type DubStatus = "off" | "connecting" | "listening" | "translating" | "playing" | "reconnecting" | "unavailable";

export interface DubState {
  status: DubStatus;
  /** Why dubbing is unavailable or reconnecting (English, from the shared code). */
  error: string | null;
  /**
   * How far the dubbed speech trails the original, in ms: from the moment a phrase was
   * finalized by speech-to-text to the moment its dubbed audio started playing. Null until measured.
   */
  delayMs: number | null;
  /** Phrases skipped to stay close to live (since dubbing was enabled). */
  skipped: number;
}

export const INITIAL_DUB_STATE: DubState = { status: "off", error: null, delayMs: null, skipped: 0 };

/** A finished, translated phrase on its way to speech synthesis. */
export interface DubSegment {
  /** Increasing per pipeline; used to keep order and drop duplicates. */
  seq: number;
  text: string;
  /** Wall-clock ms when the original words were finalized (the delay measurement's start). */
  spokenAt: number;
}

