/**
 * Front half of live dubbing: finalized transcript lines → natural phrases → translated text,
 * in the order they were spoken. Interim results are never used, so the dub never repeats or
 * corrects itself.
 *
 * Runs wherever Chrome's translator works (the extension's side panel, a web page). The
 * translated phrases go to a DubOutput, which may live in another context.
 */
import { AUTO_LANGUAGE } from "../settings";
import { translateText } from "../translate";
import type { TranscriptEvent, TranscriptLine, TranslationIssue } from "../types";
import type { DubSegment } from "./types";

export interface PhraseOptions {
  /** Wait this long for a short fragment's continuation before sending it alone. */
  holdMs?: number;
  /** Never hold a phrase longer than this since its first words were finalized. */
  maxHoldMs?: number;
  /** Phrases older than this when they're ready to speak are skipped (stay close to live). */
  maxLagMs?: number;
  /** Injected for tests. */
  translate?: typeof translateText;
  now?: () => number;
}

export interface PhraseHandlers {
  onSegment: (segment: DubSegment) => void;
  /** True while at least one phrase is being translated. */
  onTranslating?: (busy: boolean) => void;
  /** A phrase couldn't be translated (null clears). */
  onIssue?: (issue: TranslationIssue | null) => void;
  /** A phrase was dropped because it got too old. */
  onSkipped?: () => void;
}

interface Pending {
  text: string;
  spokenAt: number;
  firstAt: number;
  language: string | undefined;
}

const SENTENCE_END = /[.!?。！？…]["'”’)\]]*$/u;
/** Scripts written without spaces: count characters instead of words. */
const NO_SPACES = /[぀-ヿ㐀-鿿가-힯]/u;

function size(text: string): number {
  return NO_SPACES.test(text) ? Math.ceil(text.replace(/\s/g, "").length / 3) : text.split(/\s+/).filter(Boolean).length;
}

/** Whether a phrase is ready to speak without waiting for more words. */
export function isCompletePhrase(text: string): boolean {
  const n = size(text);
  return n >= 12 || (n >= 3 && SENTENCE_END.test(text.trim()));
}

export class DubPhrasePipeline {
  private spoken = AUTO_LANGUAGE;
  private target = "";
  private active = false;
  private since = 0;
  private generation = 0;
  private seq = 0;
  private seen = new Set<string>();
  private pending: Pending | null = null;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private chain: Promise<void> = Promise.resolve();
  private inFlight = 0;
  private readonly holdMs: number;
  private readonly maxHoldMs: number;
  private readonly maxLagMs: number;
  private readonly translate: typeof translateText;
  private readonly now: () => number;

  constructor(
    private readonly handlers: PhraseHandlers,
    opts: PhraseOptions = {},
  ) {
    this.holdMs = opts.holdMs ?? 900;
    this.maxHoldMs = opts.maxHoldMs ?? 2000;
    this.maxLagMs = opts.maxLagMs ?? 8000;
    this.translate = opts.translate ?? translateText;
    this.now = opts.now ?? Date.now;
  }

  /** `spoken`: Deepgram code or "multi". `target`: translator code of the dubbed speech. */
  configure(spoken: string, target: string): void {
    const s = spoken || AUTO_LANGUAGE;
    if (s === this.spoken && target === this.target) return;
    this.spoken = s;
    this.target = target;
    // A new language makes everything in flight outdated.
    this.clear();
  }

  /** Start dubbing from now on: lines finalized before this call are never spoken. */
  start(): void {
    if (this.active) return;
    this.active = true;
    this.since = this.now();
    this.clear();
  }

  stop(): void {
    this.active = false;
    this.clear();
  }

  get isActive(): boolean {
    return this.active;
  }

  /** Drop held and in-flight phrases (seek, language change, new video). */
  clear(): void {
    this.generation += 1;
    this.pending = null;
    if (this.timer) clearTimeout(this.timer);
    this.timer = null;
    this.chain = Promise.resolve();
    if (this.inFlight > 0) {
      this.inFlight = 0;
      this.handlers.onTranslating?.(false);
    }
  }

  /** Feed every transcript event. */
  handle(event: TranscriptEvent): void {
    if (event.type === "reset") {
      this.seen.clear();
      this.clear();
      return;
    }
    if (event.type !== "line" || !this.active || !this.target) return;
    this.addLine(event.line);
  }

  private addLine(line: TranscriptLine) {
    if (this.seen.has(line.id)) return;
    this.seen.add(line.id);
    if (line.createdAt < this.since) return;
    const text = line.text.trim();
    if (!text) return;

    const p = this.pending;
    // A language switch ends the phrase: each one is translated from its own language.
    if (p && p.language !== line.language) this.emit();
    if (this.pending) {
      this.pending.text = `${this.pending.text} ${text}`;
      this.pending.spokenAt = line.createdAt;
      this.pending.language ??= line.language;
    } else {
      this.pending = { text, spokenAt: line.createdAt, firstAt: line.createdAt, language: line.language };
    }

    const cur = this.pending!;
    if (isCompletePhrase(cur.text) || this.now() - cur.firstAt >= this.maxHoldMs) {
      this.emit();
      return;
    }
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      this.timer = null;
      this.emit();
    }, this.holdMs);
  }

  private sourceFor(detected: string | undefined): string | null {
    return this.spoken === AUTO_LANGUAGE ? (detected ?? null) : this.spoken;
  }

  private emit() {
    const p = this.pending;
    this.pending = null;
    if (this.timer) clearTimeout(this.timer);
    this.timer = null;
    if (!p) return;

    const generation = this.generation;
    const target = this.target;
    const source = this.sourceFor(p.language);
    const seq = ++this.seq;
    // Translations run in parallel but are released in spoken order.
    this.setBusy(+1);
    const translated = source
      ? this.translate(p.text, source, target).catch(
          (err): Awaited<ReturnType<typeof translateText>> => ({
            ok: false,
            issue: { source, target, kind: "failed", detail: String(err) },
          }),
        )
      : Promise.resolve<Awaited<ReturnType<typeof translateText>>>({
          ok: false,
          issue: { source: "", target, kind: "unsupported" },
        });

    this.chain = this.chain.then(async () => {
      const result = await translated;
      if (generation !== this.generation) return;
      this.setBusy(-1);
      if (!result.ok) {
        this.handlers.onIssue?.(result.issue);
        return;
      }
      this.handlers.onIssue?.(null);
      if (this.now() - p.spokenAt > this.maxLagMs) {
        this.handlers.onSkipped?.();
        return;
      }
      const text = result.text.trim();
      if (text) this.handlers.onSegment({ seq, text, spokenAt: p.spokenAt });
    });
  }

  private setBusy(delta: number) {
    const before = this.inFlight;
    this.inFlight = Math.max(0, this.inFlight + delta);
    if ((before === 0) !== (this.inFlight === 0)) this.handlers.onTranslating?.(this.inFlight > 0);
  }
}

/**
 * Deepgram Flux TTS over the streaming `/v2/speak` WebSocket.
 *
 * One persistent socket per voice: each phrase is one turn (`Speak` + `Flush`), and raw
 * linear16 audio streams back as binary frames while the turn is synthesized. The server
 * handles turns in order, so audio frames map to phrases first-in, first-out using its
 * `SpeechStarted` / `SpeechMetadata` markers.
 *
 * Auth is the same as speech-to-text: browsers can't set headers on a WebSocket, so the
 * credential goes in the subprotocol (`["bearer", jwt]` or `["token", userKey]`).
 */
import type { DeepgramCredential } from "../types";
import type { DubSegment } from "./types";

export const DEEPGRAM_SPEAK_V2_URL = "wss://api.deepgram.com/v2/speak";
export const DUB_SAMPLE_RATE = 24000;

export function buildSpeakUrl(voice: string, base = DEEPGRAM_SPEAK_V2_URL, sampleRate = DUB_SAMPLE_RATE): string {
  const p = new URLSearchParams({ model: voice, encoding: "linear16", sample_rate: String(sampleRate) });
  return `${base}?${p.toString()}`;
}

export type SpeakerStatus = "idle" | "connecting" | "open" | "reconnecting" | "failed";

export interface FluxSpeakerOptions {
  voice: string;
  /** Called for every (re)connect, like the transcription session's `getToken`. */
  getToken: () => Promise<string | DeepgramCredential>;
  /** PCM16 mono audio for a phrase, in order. */
  onAudio: (seq: number, pcm: Int16Array) => void;
  /** All audio for a phrase has arrived. */
  onTurnEnd?: (seq: number) => void;
  onStatus?: (status: SpeakerStatus, error: string | null) => void;
  baseUrl?: string;
  sampleRate?: number;
  maxReconnectAttempts?: number;
  /** Close the socket after this long without phrases (the server closes idle ones at 60 s). */
  idleCloseMs?: number;
  /** At most this many turns per minute; extra phrases are merged into the next turn. */
  maxTurnsPerMinute?: number;
  /** Injected for tests. */
  WebSocketImpl?: typeof WebSocket;
}

interface Turn {
  seq: number;
  /** Every phrase merged into this turn (audio is reported under the first). */
  seqs: number[];
}

type ServerMessage = { type: string; code?: string; description?: string; speech_id?: string };

export class FluxSpeaker {
  private ws: WebSocket | null = null;
  private queued: DubSegment[] = [];
  private turns: Turn[] = [];
  private current: Turn | null = null;
  private attempts = 0;
  private everOpened = false;
  private closed = false;
  private status: SpeakerStatus = "idle";
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private idleTimer: ReturnType<typeof setTimeout> | null = null;
  private turnTimer: ReturnType<typeof setTimeout> | null = null;
  private turnTimes: number[] = [];
  private oddByte: number | null = null;
  private lastError: string | null = null;

  constructor(private readonly opts: FluxSpeakerOptions) {}

  get voice(): string {
    return this.opts.voice;
  }

  /** Queue a phrase; connects on demand. */
  speak(segment: DubSegment): void {
    if (this.closed || this.status === "failed") return;
    this.queued.push(segment);
    this.touch();
    if (this.ws?.readyState === 1) this.pump();
    else if (!this.ws && !this.reconnectTimer) void this.connect();
  }

  /**
   * Drop everything queued or being synthesized (seek, stale backlog). Flux has no "clear"
   * message, so the socket is closed and the next phrase opens a fresh one.
   */
  reset(): void {
    this.queued = [];
    this.turns = [];
    this.current = null;
    this.dropSocket();
    if (this.status !== "failed") this.setStatus("idle");
  }

  /** Stop for good. */
  close(): void {
    this.closed = true;
    this.queued = [];
    this.turns = [];
    this.current = null;
    if (this.idleTimer) clearTimeout(this.idleTimer);
    this.dropSocket();
  }

  /* ----------------------------- internals ----------------------------- */

  private setStatus(status: SpeakerStatus, error: string | null = null) {
    if (status === this.status && error === this.lastError) return;
    this.status = status;
    this.lastError = error;
    this.opts.onStatus?.(status, error);
  }

  private dropSocket() {
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    if (this.turnTimer) clearTimeout(this.turnTimer);
    this.reconnectTimer = null;
    this.turnTimer = null;
    const ws = this.ws;
    this.ws = null;
    this.oddByte = null;
    if (ws) {
      ws.onopen = ws.onmessage = ws.onclose = ws.onerror = null;
      try {
        if (ws.readyState === 1) ws.send(JSON.stringify({ type: "Close" }));
        ws.close(1000);
      } catch {
        /* already closing */
      }
    }
  }

  private touch() {
    if (this.idleTimer) clearTimeout(this.idleTimer);
    this.idleTimer = setTimeout(() => {
      if (this.queued.length === 0 && this.turns.length === 0 && !this.current) {
        this.dropSocket();
        if (this.status !== "failed") this.setStatus("idle");
      } else this.touch();
    }, this.opts.idleCloseMs ?? 45_000);
  }

  private async connect() {
    if (this.closed) return;
    this.setStatus(this.attempts === 0 ? "connecting" : "reconnecting", this.attempts === 0 ? null : this.lastError);
    let credential: DeepgramCredential;
    try {
      const token = await this.opts.getToken();
      credential = typeof token === "string" ? { type: "bearer", value: token } : token;
    } catch (err) {
      return this.retry((err as Error).message, (err as { fatal?: boolean }).fatal === true);
    }
    if (this.closed || this.ws) return;

    const WS = this.opts.WebSocketImpl ?? WebSocket;
    const ws = new WS(buildSpeakUrl(this.opts.voice, this.opts.baseUrl, this.opts.sampleRate), [credential.type, credential.value]);
    ws.binaryType = "arraybuffer";
    this.ws = ws;
    let opened = false;
    let serverError: string | null = null;

    ws.onopen = () => {
      opened = true;
      this.everOpened = true;
      this.attempts = 0;
      this.setStatus("open");
      this.pump();
    };
    ws.onmessage = (e: MessageEvent) => {
      if (this.ws !== ws) return;
      if (typeof e.data === "string") {
        let msg: ServerMessage;
        try {
          msg = JSON.parse(e.data) as ServerMessage;
        } catch {
          return;
        }
        if (msg.type === "Error") serverError = msg.description ? `Deepgram: ${msg.description}` : `Deepgram error ${msg.code ?? ""}`.trim();
        this.onControl(msg);
      } else {
        this.onBinary(e.data as ArrayBuffer);
      }
    };
    ws.onerror = () => {
      /* onclose follows */
    };
    ws.onclose = (e: CloseEvent) => {
      if (this.ws !== ws) return;
      this.ws = null;
      this.oddByte = null;
      // Turns in flight are lost: re-sending them could repeat words already played.
      this.turns = [];
      this.current = null;
      const idle = this.queued.length === 0;
      // The server closes quiet sockets (NET-0004); that's not a failure.
      if (opened && idle && (e.code === 1000 || /NET-0004/.test(e.reason))) {
        this.setStatus("idle");
        return;
      }
      if (!opened && !this.everOpened && credential.type === "token") {
        return this.retry("Deepgram didn't accept your API key for speech synthesis.", true);
      }
      const reason = serverError ?? (e.reason ? `Deepgram closed the speech connection: ${e.reason}` : opened ? `Speech connection lost (code ${e.code}).` : "Could not connect to Deepgram speech synthesis.");
      this.retry(reason, false);
    };
  }

  private retry(reason: string, fatal: boolean) {
    this.ws = null;
    this.attempts += 1;
    const max = this.opts.maxReconnectAttempts ?? 4;
    if (fatal || this.attempts > max) {
      this.queued = [];
      this.setStatus("failed", fatal ? reason : `${reason} Gave up after ${max} attempts.`);
      return;
    }
    this.lastError = reason;
    this.setStatus("reconnecting", reason);
    const delay = Math.min(400 * 2 ** (this.attempts - 1), 5000);
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      void this.connect();
    }, delay);
  }

  /** Send queued phrases as turns, merging them when the turn budget is spent. */
  private pump() {
    const ws = this.ws;
    if (!ws || ws.readyState !== 1 || this.queued.length === 0) return;
    const now = Date.now();
    const limit = this.opts.maxTurnsPerMinute ?? 20;
    this.turnTimes = this.turnTimes.filter((t) => now - t < 60_000);
    if (this.turnTimes.length >= limit) {
      if (!this.turnTimer) {
        const wait = 60_000 - (now - this.turnTimes[0]!) + 10;
        this.turnTimer = setTimeout(() => {
          this.turnTimer = null;
          this.pump();
        }, wait);
      }
      return;
    }
    // Everything waiting goes out as one turn (usually that's a single phrase).
    const batch = this.queued;
    this.queued = [];
    const text = batch.map((s) => s.text).join(" ");
    this.turns.push({ seq: batch[0]!.seq, seqs: batch.map((s) => s.seq) });
    this.turnTimes.push(now);
    ws.send(JSON.stringify({ type: "Speak", text }));
    ws.send(JSON.stringify({ type: "Flush" }));
  }

  private onControl(msg: ServerMessage) {
    switch (msg.type) {
      case "SpeechStarted":
        this.current = this.turns.shift() ?? this.current;
        break;
      case "SpeechMetadata": {
        const turn = this.current ?? this.turns.shift();
        this.current = null;
        this.oddByte = null;
        if (turn) this.opts.onTurnEnd?.(turn.seq);
        this.touch();
        break;
      }
      case "Warning":
        // A turn with nothing to say produces no audio and no SpeechStarted: forget it.
        if (!this.current && (msg.code === "NO_SYNTHESIZABLE_TEXT" || msg.code === "NO_AUDIO_GENERATED")) {
          const turn = this.turns.shift();
          if (turn) this.opts.onTurnEnd?.(turn.seq);
        }
        break;
    }
  }

  private onBinary(data: ArrayBuffer) {
    if (!this.current) this.current = this.turns.shift() ?? null;
    const turn = this.current;
    if (!turn) return;
    let bytes = new Uint8Array(data);
    // Keep 16-bit samples whole if a frame ever splits one.
    if (this.oddByte !== null) {
      const joined = new Uint8Array(bytes.length + 1);
      joined[0] = this.oddByte;
      joined.set(bytes, 1);
      bytes = joined;
      this.oddByte = null;
    }
    if (bytes.length % 2 === 1) {
      this.oddByte = bytes[bytes.length - 1]!;
      bytes = bytes.subarray(0, bytes.length - 1);
    }
    if (bytes.length === 0) return;
    const pcm = new Int16Array(bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.length));
    this.opts.onAudio(turn.seq, pcm);
  }
}

