/**
 * Playback queue for dubbed speech (Web Audio).
 *
 * PCM chunks are scheduled back to back on one clock, so phrases play in order and never
 * overlap. A phrase whose first word would start too long after the original was spoken is
 * skipped, which keeps a livestream's dub close to live instead of replaying an ever-older
 * backlog. Nothing is stored: chunks are dropped as soon as they've played.
 */
import { DUB_SAMPLE_RATE } from "./flux-tts";

/** The parts of AudioContext the player uses (a fake in tests). */
export interface DubAudioContext {
  readonly currentTime: number;
  readonly destination: AudioNode;
  readonly state: AudioContextState;
  createGain(): GainNode;
  createBuffer(channels: number, length: number, sampleRate: number): AudioBuffer;
  createBufferSource(): AudioBufferSourceNode;
  suspend(): Promise<void>;
  resume(): Promise<void>;
  close(): Promise<void>;
}

export interface DubPlayerOptions {
  sampleRate?: number;
  /** Skip a phrase that would start more than this long after it was spoken. */
  maxLagMs?: number;
  /** Small scheduling lead so the first chunk isn't clipped. */
  leadSeconds?: number;
  createContext?: () => DubAudioContext;
  now?: () => number;
  /** Dubbed audio started (true) or ran out (false). */
  onPlaying?: (playing: boolean) => void;
  /** Delay of the phrase that just started, in ms (see DubState.delayMs). */
  onDelay?: (ms: number) => void;
  onSkipped?: () => void;
}

interface Phrase {
  spokenAt: number;
  /** Paused time already counted when the phrase was registered. */
  pausedBase: number;
  state: "waiting" | "playing" | "skipped";
}

export class DubPlayer {
  private ctx: DubAudioContext | null = null;
  private gain: GainNode | null = null;
  private volume = 1;
  private nextTime = 0;
  private phrases = new Map<number, Phrase>();
  private sources = new Set<AudioBufferSourceNode>();
  private paused = false;
  private pausedSince = 0;
  private pausedTotal = 0;
  private playing = false;
  private readonly sampleRate: number;
  private readonly maxLagMs: number;
  private readonly lead: number;
  private readonly now: () => number;

  constructor(private readonly opts: DubPlayerOptions = {}) {
    this.sampleRate = opts.sampleRate ?? DUB_SAMPLE_RATE;
    this.maxLagMs = opts.maxLagMs ?? 8000;
    this.lead = opts.leadSeconds ?? 0.05;
    this.now = opts.now ?? Date.now;
  }

  private context(): DubAudioContext {
    if (!this.ctx) {
      const ctx = this.opts.createContext?.() ?? (new AudioContext({ latencyHint: "interactive" }) as DubAudioContext);
      const gain = ctx.createGain();
      gain.gain.value = this.volume;
      gain.connect(ctx.destination);
      this.ctx = ctx;
      this.gain = gain;
      if (this.paused) void ctx.suspend().catch(() => undefined);
      else if (ctx.state === "suspended") void ctx.resume().catch(() => undefined);
    }
    return this.ctx;
  }

  /** Register a phrase before its audio arrives. */
  begin(seq: number, spokenAt: number): void {
    if (!this.phrases.has(seq)) this.phrases.set(seq, { spokenAt, pausedBase: this.pausedMs(), state: "waiting" });
  }

  /** Audio for a phrase (PCM16 mono). Unknown phrases are ignored (they were cleared). */
  push(seq: number, pcm: Int16Array): void {
    const phrase = this.phrases.get(seq);
    if (!phrase || phrase.state === "skipped" || pcm.length === 0) return;
    const ctx = this.context();
    const start = Math.max(ctx.currentTime + this.lead, this.nextTime);

    if (phrase.state === "waiting") {
      const age = this.now() - phrase.spokenAt - (this.pausedMs() - phrase.pausedBase);
      const delay = Math.round(age + (start - ctx.currentTime) * 1000);
      if (delay > this.maxLagMs) {
        phrase.state = "skipped";
        this.opts.onSkipped?.();
        return;
      }
      phrase.state = "playing";
      this.opts.onDelay?.(delay);
    }

    const buffer = ctx.createBuffer(1, pcm.length, this.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < pcm.length; i++) data[i] = pcm[i]! / 0x8000;
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(this.gain!);
    source.onended = () => {
      this.sources.delete(source);
      try {
        source.disconnect();
      } catch {
        /* already disconnected */
      }
      if (this.sources.size === 0) this.setPlaying(false);
    };
    this.sources.add(source);
    source.start(start);
    this.nextTime = start + pcm.length / this.sampleRate;
    this.setPlaying(true);
  }

  /** All audio for a phrase arrived; forget it once nothing more can come. */
  end(seq: number): void {
    this.phrases.delete(seq);
  }

  /** Stop and drop everything queued (seek, new language, dubbing off). */
  clear(): void {
    this.phrases.clear();
    for (const s of this.sources) {
      s.onended = null;
      try {
        s.stop();
        s.disconnect();
      } catch {
        /* not started or already stopped */
      }
    }
    this.sources.clear();
    this.nextTime = 0;
    this.setPlaying(false);
  }

  setVolume(volume: number): void {
    this.volume = Math.min(1, Math.max(0, volume));
    if (this.gain) this.gain.gain.value = this.volume;
  }

  /** Follow the source video: a paused video pauses the dub where it is. */
  setPaused(paused: boolean): void {
    if (paused === this.paused) return;
    this.paused = paused;
    if (paused) this.pausedSince = this.now();
    else this.pausedTotal += this.now() - this.pausedSince;
    if (!this.ctx) return;
    void (paused ? this.ctx.suspend() : this.ctx.resume()).catch(() => undefined);
  }

  /** Seconds of dubbed audio scheduled but not yet played. */
  get backlogSeconds(): number {
    return this.ctx ? Math.max(0, this.nextTime - this.ctx.currentTime) : 0;
  }

  async close(): Promise<void> {
    this.clear();
    const ctx = this.ctx;
    this.ctx = null;
    this.gain = null;
    await ctx?.close().catch(() => undefined);
  }

  private pausedMs() {
    return this.pausedTotal + (this.paused ? this.now() - this.pausedSince : 0);
  }

  private setPlaying(playing: boolean) {
    if (playing === this.playing) return;
    this.playing = playing;
    this.opts.onPlaying?.(playing);
  }
}

/**
 * Back half of live dubbing: translated phrases → Flux TTS → playback queue, plus the
 * status the UI shows. Runs in a context whose audio is NOT being captured (the extension's
 * offscreen document), so the dub is never transcribed again.
 */
import type { DeepgramCredential } from "../types";
import { FluxSpeaker, type SpeakerStatus } from "./flux-tts";
import { DubPlayer, type DubAudioContext } from "./player";
import { INITIAL_DUB_STATE, type DubSegment, type DubState } from "./types";

export interface DubOutputOptions {
  getToken: () => Promise<string | DeepgramCredential>;
  onState?: (state: DubState) => void;
  /** Livestreams should stay closer to live than recorded videos. */
  maxLagMs?: number;
  speakBaseUrl?: string;
  createContext?: () => DubAudioContext;
  WebSocketImpl?: typeof WebSocket;
}

export class DubOutput {
  private state: DubState = INITIAL_DUB_STATE;
  private speaker: FluxSpeaker | null = null;
  private speakerStatus: SpeakerStatus = "idle";
  private speakerError: string | null = null;
  private translating = false;
  private playing = false;
  private lastSeq = 0;
  private readonly player: DubPlayer;

  constructor(private readonly opts: DubOutputOptions) {
    this.player = new DubPlayer({
      maxLagMs: opts.maxLagMs,
      createContext: opts.createContext,
      onPlaying: (p) => {
        this.playing = p;
        this.refresh();
      },
      onDelay: (ms) => this.update({ delayMs: ms }),
      onSkipped: () => this.update({ skipped: this.state.skipped + 1 }),
    });
  }

  getState(): DubState {
    return this.state;
  }

  get enabled(): boolean {
    return this.speaker !== null;
  }

  /** Turn dubbing on (or switch voice). Everything queued for an older voice is dropped. */
  enable(voice: string, dubVolume: number): void {
    this.player.setVolume(dubVolume);
    if (this.speaker?.voice === voice && this.speakerStatus !== "failed") return;
    this.teardownSpeaker();
    this.player.clear();
    this.lastSeq = 0;
    this.speakerStatus = "idle";
    this.speakerError = null;
    this.state = { ...INITIAL_DUB_STATE, status: "listening" };
    this.speaker = new FluxSpeaker({
      voice,
      getToken: this.opts.getToken,
      baseUrl: this.opts.speakBaseUrl,
      WebSocketImpl: this.opts.WebSocketImpl,
      onAudio: (seq, pcm) => this.player.push(seq, pcm),
      onTurnEnd: (seq) => this.player.end(seq),
      onStatus: (status, error) => {
        this.speakerStatus = status;
        this.speakerError = error;
        if (status === "failed") this.player.clear();
        this.refresh();
      },
    });
    this.refresh();
  }

  /** Turn dubbing off: stop speech now and cancel pending synthesis. */
  disable(): void {
    this.teardownSpeaker();
    this.player.clear();
    this.translating = false;
    this.playing = false;
    this.lastSeq = 0;
    this.speakerStatus = "idle";
    this.speakerError = null;
    this.update({ ...INITIAL_DUB_STATE });
  }

  /** A translated phrase. Repeats (same or older `seq`) are ignored. */
  speak(segment: DubSegment): void {
    if (!this.speaker || segment.seq <= this.lastSeq) return;
    this.lastSeq = segment.seq;
    this.player.begin(segment.seq, segment.spokenAt);
    this.speaker.speak(segment);
  }

  /** The front half is translating a phrase (status only). */
  setTranslating(busy: boolean): void {
    this.translating = busy;
    this.refresh();
  }

  /** Drop queued and in-flight speech (seek, new video, new language). */
  clear(): void {
    this.speaker?.reset();
    this.player.clear();
    this.lastSeq = 0;
  }

  setVolume(volume: number): void {
    this.player.setVolume(volume);
  }

  setPaused(paused: boolean): void {
    this.player.setPaused(paused);
  }

  async close(): Promise<void> {
    this.teardownSpeaker();
    await this.player.close();
  }

  private teardownSpeaker() {
    this.speaker?.close();
    this.speaker = null;
  }

  private refresh() {
    if (!this.speaker) return;
    const s = this.speakerStatus;
    if (s === "failed") return this.update({ status: "unavailable", error: this.speakerError });
    if (s === "reconnecting") return this.update({ status: "reconnecting", error: this.speakerError });
    if (this.playing) return this.update({ status: "playing", error: null });
    if (s === "connecting") return this.update({ status: "connecting", error: null });
    this.update({ status: this.translating ? "translating" : "listening", error: null });
  }

  private update(patch: Partial<DubState>) {
    const next = { ...this.state, ...patch };
    if (
      next.status === this.state.status &&
      next.error === this.state.error &&
      next.delayMs === this.state.delayMs &&
      next.skipped === this.state.skipped
    ) {
      return;
    }
    this.state = next;
    this.opts.onState?.(next);
  }
}

