import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  buildSpeakUrl,
  DubOutput,
  DubPhrasePipeline,
  DubPlayer,
  DUB_LANGUAGES,
  FluxSpeaker,
  isCompletePhrase,
  normalizeDubSettings,
  pickVoice,
  voicesFor,
  type DubAudioContext,
  type DubSegment,
  type DubState,
} from "../src/core/dubbing";
import type { TranscriptLine } from "../src/core/types";

/* ------------------------------ fakes ------------------------------ */

class FakeSocket {
  static all: FakeSocket[] = [];
  readyState = 0;
  binaryType = "blob";
  sent: string[] = [];
  onopen: (() => void) | null = null;
  onmessage: ((e: { data: unknown }) => void) | null = null;
  onclose: ((e: { code: number; reason: string }) => void) | null = null;
  onerror: (() => void) | null = null;
  constructor(
    readonly url: string,
    readonly protocols: string[],
  ) {
    FakeSocket.all.push(this);
  }
  send(data: string) {
    this.sent.push(data);
  }
  close() {
    this.readyState = 3;
  }
  open() {
    this.readyState = 1;
    this.onopen?.();
  }
  json(msg: object) {
    this.onmessage?.({ data: JSON.stringify(msg) });
  }
  audio(samples: number[]) {
    this.onmessage?.({ data: new Int16Array(samples).buffer });
  }
  serverClose(code = 1006, reason = "") {
    this.readyState = 3;
    this.onclose?.({ code, reason });
  }
  get texts() {
    return this.sent.map((s) => JSON.parse(s) as { type: string; text?: string }).filter((m) => m.type === "Speak").map((m) => m.text);
  }
}

interface FakeSource {
  buffer: { length: number } | null;
  startAt: number | null;
  stopped: boolean;
  onended: (() => void) | null;
}

function fakeContext() {
  const sources: FakeSource[] = [];
  const ctx = {
    currentTime: 0,
    state: "running" as AudioContextState,
    destination: {} as AudioNode,
    sources,
    createGain: () => ({ gain: { value: 1 }, connect() {}, disconnect() {} }) as unknown as GainNode,
    createBuffer: (_c: number, length: number) => ({ length, getChannelData: () => new Float32Array(length) }) as unknown as AudioBuffer,
    createBufferSource: () => {
      const s: FakeSource & Record<string, unknown> = {
        buffer: null,
        startAt: null,
        stopped: false,
        onended: null,
        connect() {},
        disconnect() {},
        start(t: number) {
          s.startAt = t;
        },
        stop() {
          s.stopped = true;
        },
      };
      sources.push(s);
      return s as unknown as AudioBufferSourceNode;
    },
    suspend: vi.fn(async () => {
      ctx.state = "suspended";
    }),
    resume: vi.fn(async () => {
      ctx.state = "running";
    }),
    close: vi.fn(async () => undefined),
  };
  return ctx;
}

const flush = () => new Promise((r) => setTimeout(r, 0));
const ws = () => FakeSocket.all[FakeSocket.all.length - 1]!;

beforeEach(() => {
  FakeSocket.all = [];
});
afterEach(() => {
  vi.useRealTimers();
});

/* ------------------------------ voices ------------------------------ */

describe("dubbing languages and voices", () => {
  it("only offers languages the translator and Flux TTS both support", () => {
