/* ------------------------------ phrases ------------------------------ */

let lineId = 0;
function line(text: string, createdAt: number, language?: string): { type: "line"; line: TranscriptLine } {
  return { type: "line", line: { id: `l${++lineId}`, text, start: 0, end: 0, mediaStart: null, mediaEnd: null, createdAt, language } };
}

describe("DubPhrasePipeline", () => {
  const translate = vi.fn(async (text: string, source: string, target: string) => ({ ok: true as const, text: `[${source}>${target}] ${text}` }));

  it("knows when a phrase is complete", () => {
    expect(isCompletePhrase("Hello there, friends.")).toBe(true);
    expect(isCompletePhrase("Hi.")).toBe(false);
    expect(isCompletePhrase("and then we")).toBe(false);
  });

  it("speaks complete sentences right away and ignores lines from before it started", async () => {
    let now = 1000;
    const out: DubSegment[] = [];
    const p = new DubPhrasePipeline({ onSegment: (s) => out.push(s) }, { translate, now: () => now });
    p.configure("en", "es");
    p.handle(line("Said before dubbing was on.", 900));
    p.start();
    now = 2000;
    p.handle(line("Welcome back to the show.", 2000));
    await flush();
    expect(out.map((s) => s.text)).toEqual(["[en>es] Welcome back to the show."]);
    expect(out[0]!.spokenAt).toBe(2000);
  });

  it("groups short fragments into one phrase", async () => {
    vi.useFakeTimers();
    let now = 0;
    const out: DubSegment[] = [];
    const p = new DubPhrasePipeline({ onSegment: (s) => out.push(s) }, { translate, now: () => now, holdMs: 500 });
    p.configure("en", "es");
    p.start();
    p.handle(line("So", 10));
    p.handle(line("anyway", 20));
    expect(out).toHaveLength(0);
    await vi.advanceTimersByTimeAsync(600);
    expect(out.map((s) => s.text)).toEqual(["[en>es] So anyway"]);
  });

  it("releases translations in spoken order even when they finish out of order", async () => {
    const slowFirst = vi.fn(async (text: string) => {
      await new Promise((r) => setTimeout(r, text.startsWith("First") ? 20 : 1));
      return { ok: true as const, text };
    });
    const out: DubSegment[] = [];
    const p = new DubPhrasePipeline({ onSegment: (s) => out.push(s) }, { translate: slowFirst });
    p.configure("en", "es");
    p.start();
    p.handle(line("First sentence goes here.", Date.now()));
    p.handle(line("Second sentence goes here.", Date.now()));
    await new Promise((r) => setTimeout(r, 40));
    expect(out.map((s) => s.text)).toEqual(["First sentence goes here.", "Second sentence goes here."]);
    expect(out[0]!.seq).toBeLessThan(out[1]!.seq);
  });

  it("drops in-flight phrases when the language changes and skips stale ones", async () => {
    let now = 0;
    const out: DubSegment[] = [];
    const onSkipped = vi.fn();
    const p = new DubPhrasePipeline({ onSegment: (s) => out.push(s), onSkipped }, { translate, now: () => now, maxLagMs: 5000 });
    p.configure("en", "es");
    p.start();
    p.handle(line("This one is outdated now.", 0));
    p.configure("en", "fr");
    await flush();
    expect(out).toHaveLength(0);

    p.handle(line("This one waited far too long.", 0));
    now = 9000;
    await flush();
    expect(out).toHaveLength(0);
    expect(onSkipped).toHaveBeenCalledOnce();
  });

  it("never speaks the same line twice", async () => {
    const out: DubSegment[] = [];
    const p = new DubPhrasePipeline({ onSegment: (s) => out.push(s) }, { translate });
    p.configure("en", "es");
    p.start();
    const l = line("Only say this once please.", Date.now());
    p.handle(l);
    p.handle(l);
    await flush();
    expect(out).toHaveLength(1);
  });

  it("translates from the detected language when the spoken language is auto", async () => {
    const out: DubSegment[] = [];
    const p = new DubPhrasePipeline({ onSegment: (s) => out.push(s) }, { translate });
    p.configure("multi", "en");
    p.start();
    p.handle(line("Bonjour à tous et bienvenue.", Date.now(), "fr"));
    await flush();
    expect(out[0]!.text).toBe("[fr>en] Bonjour à tous et bienvenue.");
  });
});

/* ------------------------------ speaker ------------------------------ */

function speaker(extra: Partial<ConstructorParameters<typeof FluxSpeaker>[0]> = {}) {
  const audio: Array<[number, number[]]> = [];
  const ends: number[] = [];
  const statuses: string[] = [];
  const s = new FluxSpeaker({
    voice: "flux-carmen-es",
    getToken: async () => "jwt",
    onAudio: (seq, pcm) => audio.push([seq, [...pcm]]),
    onTurnEnd: (seq) => ends.push(seq),
    onStatus: (st) => statuses.push(st),
    WebSocketImpl: FakeSocket as unknown as typeof WebSocket,
    ...extra,
  });
  return { s, audio, ends, statuses };
}

const seg = (seq: number, text = `phrase ${seq}`): DubSegment => ({ seq, text, spokenAt: Date.now() });

describe("FluxSpeaker", () => {
  it("authenticates like speech-to-text and sends each phrase as a turn", async () => {
    const { s } = speaker();
    s.speak(seg(1, "Hola a todos."));
    await flush();
    expect(ws().protocols).toEqual(["bearer", "jwt"]);
    expect(ws().url).toContain("model=flux-carmen-es");
    ws().open();
    expect(ws().sent.map((x) => JSON.parse(x).type)).toEqual(["Speak", "Flush"]);
    expect(ws().texts).toEqual(["Hola a todos."]);
  });

  it("maps audio to phrases in order using the turn markers", async () => {
    const { s, audio, ends } = speaker();
    s.speak(seg(1));
    s.speak(seg(2));
    await flush();
    ws().open();
    s.speak(seg(3));
    // Phrases 1 and 2 were queued while connecting: one turn. Phrase 3 is its own turn.
    expect(ws().texts).toEqual(["phrase 1 phrase 2", "phrase 3"]);
    ws().json({ type: "SpeechStarted", speech_id: "a" });
    ws().audio([1, 2]);
    ws().json({ type: "SpeechMetadata", speech_id: "a" });
    ws().json({ type: "SpeechStarted", speech_id: "b" });
    ws().audio([3]);
    ws().json({ type: "SpeechMetadata", speech_id: "b" });
    expect(audio).toEqual([
      [1, [1, 2]],
      [3, [3]],
    ]);
    expect(ends).toEqual([1, 3]);
  });

  it("merges phrases instead of exceeding the turn budget", async () => {
    vi.useFakeTimers();
    const { s } = speaker({ maxTurnsPerMinute: 1 });
    s.speak(seg(1));
    await vi.advanceTimersByTimeAsync(0);
    ws().open();
    s.speak(seg(2));
    s.speak(seg(3));
    expect(ws().texts).toEqual(["phrase 1"]);
    await vi.advanceTimersByTimeAsync(61_000);
    expect(ws().texts).toEqual(["phrase 1", "phrase 2 phrase 3"]);
  });

  it("reset closes the socket so nothing outdated is spoken", async () => {
    const { s, audio } = speaker();
    s.speak(seg(1));
    await flush();
    const first = ws();
    first.open();
    s.reset();
    expect(first.readyState).toBe(3);
    first.audio([9]); // late frame from the old socket
    expect(audio).toEqual([]);
    s.speak(seg(2));
    await flush();
    expect(FakeSocket.all).toHaveLength(2);
  });

  it("gives up on a rejected user key without retrying", async () => {
    const { s, statuses } = speaker({ getToken: async () => ({ type: "token", value: "bad" }) });
    s.speak(seg(1));
    await flush();
    ws().serverClose(1006);
    expect(statuses.at(-1)).toBe("failed");
    expect(FakeSocket.all).toHaveLength(1);
  });

  it("reconnects after a dropped connection, without re-sending phrases already sent", async () => {
    vi.useFakeTimers();
    const { s, statuses } = speaker();
    s.speak(seg(1));
    await vi.advanceTimersByTimeAsync(0);
    ws().open();
    s.speak(seg(2));
    // Drop while phrase 2 is queued but before it was sent? It was sent; queue a third.
    ws().readyState = 0;
    s.speak(seg(3));
    ws().serverClose(1011);
    expect(statuses).toContain("reconnecting");
    await vi.advanceTimersByTimeAsync(500);
    ws().open();
    expect(ws().texts).toEqual(["phrase 3"]);
  });
});

/* ------------------------------ player ------------------------------ */

describe("DubPlayer", () => {
  it("plays phrases back to back without overlapping", () => {
    const ctx = fakeContext();
    const p = new DubPlayer({ createContext: () => ctx as unknown as DubAudioContext, sampleRate: 1000, leadSeconds: 0, now: () => 0 });
    p.begin(1, 0);
    p.begin(2, 0);
    p.push(1, new Int16Array(500)); // 0.5 s
    p.push(1, new Int16Array(250)); // 0.25 s
    p.push(2, new Int16Array(1000));
    expect(ctx.sources.map((s) => s.startAt)).toEqual([0, 0.5, 0.75]);
    expect(p.backlogSeconds).toBeCloseTo(1.75);
  });

  it("skips a phrase that would start too far behind live, and reports the delay", () => {
    const ctx = fakeContext();
    const delays: number[] = [];
    const skipped = vi.fn();
    let now = 10_000;
    const p = new DubPlayer({
      createContext: () => ctx as unknown as DubAudioContext,
      sampleRate: 1000,
      leadSeconds: 0,
      maxLagMs: 3000,
      now: () => now,
      onDelay: (d) => delays.push(d),
      onSkipped: skipped,
    });
    p.begin(1, 9000); // spoken 1 s ago
    p.push(1, new Int16Array(4000)); // 4 s of audio queued
    p.begin(2, 9500); // would start 4 s from now → 4.5 s late
    p.push(2, new Int16Array(100));
    p.push(2, new Int16Array(100));
    expect(delays).toEqual([1000]);
    expect(skipped).toHaveBeenCalledOnce();
    expect(ctx.sources).toHaveLength(1);
    now = 10_001;
  });

  it("doesn't count paused time as lag, and suspends while paused", () => {
    const ctx = fakeContext();
    const skipped = vi.fn();
    let now = 0;
    const p = new DubPlayer({ createContext: () => ctx as unknown as DubAudioContext, maxLagMs: 3000, leadSeconds: 0, now: () => now, onSkipped: skipped });
    p.push(0, new Int16Array(0)); // creates the context lazily (ignored: unknown phrase)
    p.begin(1, 0);
    p.setPaused(true);
    now = 60_000;
    p.setPaused(false);
    p.push(1, new Int16Array(10));
    expect(skipped).not.toHaveBeenCalled();
    expect(ctx.sources).toHaveLength(1);
  });

  it("clear stops everything and forgets pending phrases", () => {
    const ctx = fakeContext();
    const playing: boolean[] = [];
    const p = new DubPlayer({ createContext: () => ctx as unknown as DubAudioContext, now: () => 0, onPlaying: (x) => playing.push(x) });
    p.begin(1, 0);
    p.push(1, new Int16Array(10));
    p.clear();
    p.push(1, new Int16Array(10)); // late audio for a cleared phrase
    expect(ctx.sources).toHaveLength(1);
    expect(ctx.sources[0]!.stopped).toBe(true);
    expect(playing).toEqual([true, false]);
  });
});

/* ------------------------------ output ------------------------------ */

describe("DubOutput", () => {
  function output() {
    const ctx = fakeContext();
    const states: DubState[] = [];
    const o = new DubOutput({
      getToken: async () => "jwt",
      onState: (s) => states.push(s),
      createContext: () => ctx as unknown as DubAudioContext,
      WebSocketImpl: FakeSocket as unknown as typeof WebSocket,
    });
    return { o, ctx, states };
  }

  it("goes listening → connecting → playing → listening", async () => {
    const { o, ctx, states } = output();
    o.enable("flux-carmen-es", 1);
    o.speak(seg(1, "Hola."));
    await flush();
    ws().open();
    ws().json({ type: "SpeechStarted" });
    ws().audio([1, 2, 3]);
    ctx.sources[0]!.onended?.();
    expect(states.map((s) => s.status)).toEqual(["listening", "connecting", "listening", "playing", "listening"]);
    expect(states.at(-1)!.delayMs).not.toBeNull();
  });

  it("ignores repeated phrases", async () => {
    const { o } = output();
    o.enable("flux-carmen-es", 1);
    o.speak(seg(1, "Uno."));
    o.speak(seg(1, "Uno."));
    await flush();
    ws().open();
    expect(ws().texts).toEqual(["Uno."]);
  });

  it("reports unavailable when synthesis fails for good, and resets when disabled", async () => {
    const { o, states } = output();
    const failing = new DubOutput({
      getToken: async () => ({ type: "token", value: "bad" }),
      onState: (s) => states.push(s),
      createContext: () => fakeContext() as unknown as DubAudioContext,
      WebSocketImpl: FakeSocket as unknown as typeof WebSocket,
    });
    failing.enable("flux-carmen-es", 1);
    failing.speak(seg(1));
    await flush();
    ws().serverClose(1006);
    expect(failing.getState().status).toBe("unavailable");
    expect(failing.getState().error).toMatch(/API key/);
    failing.disable();
    expect(failing.getState().status).toBe("off");
    o.disable();
  });
});

import { useId, useState, type ReactNode } from "react";
import { languageName } from "../core/settings";
import { DUB_LANGUAGES, pickVoice, voicesFor, type DubSettings } from "../core/dubbing/voices";
import type { DubState, DubStatus } from "../core/dubbing/types";
import { ChevronDownIcon } from "./icons";
import { DEFAULT_DUBBING_LABELS, type DubbingLabels } from "./labels";
import { Select } from "./Select";

export interface DubbingControlsProps {
  settings: DubSettings;
  onSettingsChange: (next: DubSettings) => void;
  /** Whether dubbing is on right now (never on by default). */
  enabled: boolean;
  onEnabledChange: (enabled: boolean) => void;
  state: DubState;
  /** False when this setup can't keep the dub out of the captured audio. */
  available?: boolean;
  /** Shown instead of the controls when unavailable. */
  unavailableNote?: ReactNode;
  /** Dubbing needs a running caption session. */
  sessionRunning: boolean;
  /** Whether the original audio's level can be changed without affecting captions. */
  canControlOriginal?: boolean;
  labels?: Partial<DubbingLabels>;
  /** Display name for a language code (defaults to English names). */
  languageName?: (code: string) => string;
  className?: string;
}

const DOT: Record<DubStatus, string> = {
  off: "bg-ink-500",
  connecting: "bg-accent animate-pulse",
  listening: "bg-ok",
  translating: "bg-accent",
  playing: "bg-ok animate-pulse",
  reconnecting: "bg-accent animate-pulse",
  unavailable: "bg-live",
};

/** Live dubbing: toggle, language, and (folded away) voice and volume. */
export function DubbingControls({
  settings,
  onSettingsChange,
  enabled,
  onEnabledChange,
  state,
  available = true,
  unavailableNote,
  sessionRunning,
  canControlOriginal = true,
  labels,
  languageName: nameOf = languageName,
  className = "",
}: DubbingControlsProps) {
  const L = { ...DEFAULT_DUBBING_LABELS, ...labels };
  const id = useId();
  const [advanced, setAdvanced] = useState(false);
  const voices = voicesFor(settings.language);
  const status: DubStatus = enabled ? state.status : "off";

  const setLanguage = (language: string) => onSettingsChange({ ...settings, language, voice: pickVoice(language, null) });

  return (
    <section aria-labelledby={`${id}-title`} className={`space-y-3 ${className}`}>
      <div className="flex items-center justify-between gap-3">
        <div className="min-w-0">
          <h3 id={`${id}-title`} className="text-sm font-semibold text-ink-100">
            {L.title}
          </h3>
          {available && (
            <p className="mt-0.5 flex items-center gap-1.5 text-xs text-ink-400" role="status" aria-live="polite">
              <span aria-hidden="true" className={`size-1.5 shrink-0 rounded-full ${DOT[status]}`} />
              <span className="min-w-0 truncate">
                {sessionRunning || enabled ? L.status[status] : L.needsSession}
                {enabled && state.delayMs !== null && status !== "unavailable" ? ` · ${L.delay(state.delayMs / 1000)}` : ""}
              </span>
            </p>
          )}
        </div>
        <button
          type="button"
          role="switch"
          aria-checked={enabled}
          aria-labelledby={`${id}-title`}
          disabled={!available || (!enabled && !sessionRunning)}
          onClick={() => onEnabledChange(!enabled)}
          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent disabled:cursor-not-allowed disabled:opacity-40 ${
            enabled ? "bg-accent" : "bg-ink-700"
          }`}
        >
          <span className={`inline-block size-5 rounded-full bg-white shadow transition-transform ${enabled ? "translate-x-5.5" : "translate-x-0.5"}`} />
        </button>
      </div>

      {!available ? (
        <div className="rounded-lg bg-ink-850 px-3 py-2.5 text-xs leading-relaxed text-ink-300 ring-1 ring-ink-700">{unavailableNote ?? L.unavailable}</div>
      ) : (
        <>
          {enabled && status === "unavailable" && state.error && (
            <p role="alert" className="rounded-lg bg-live/10 px-3 py-2 text-xs leading-relaxed text-live ring-1 ring-live/25">
              {L.failed(state.error)}
            </p>
          )}
          <div className="space-y-1.5">
            <span id={`${id}-lang`} className="block text-xs text-ink-300">
              {L.language}
            </span>
            <Select
              aria-labelledby={`${id}-lang`}
              value={settings.language}
              onChange={setLanguage}
              options={DUB_LANGUAGES.map(([code, english]) => ({ value: code, label: nameOf === languageName ? english : nameOf(code) }))}
            />
          </div>

          <button
            type="button"
            onClick={() => setAdvanced((a) => !a)}
            aria-expanded={advanced}
            aria-controls={`${id}-advanced`}
            className="inline-flex items-center gap-1.5 text-xs font-semibold text-accent hover:text-accent-strong"
          >
            {L.voiceAndVolume}
            <ChevronDownIcon size={13} className={`transition-transform ${advanced ? "rotate-180" : ""}`} />
          </button>

          {advanced && (
            <div id={`${id}-advanced`} className="space-y-4">
              <div className="space-y-1.5">
                <span id={`${id}-voice`} className="block text-xs text-ink-300">
                  {L.voice}
                </span>
                <Select
                  aria-labelledby={`${id}-voice`}
                  value={settings.voice}
                  onChange={(voice) => onSettingsChange({ ...settings, voice })}
                  options={voices.map((v) => ({
                    value: v.id,
                    label: [v.name, L.gender[v.gender], v.accent].filter(Boolean).join(" · "),
                  }))}
                />
              </div>
              <Slider
                label={L.originalVolume}
                value={settings.originalVolume}
                onChange={(originalVolume) => onSettingsChange({ ...settings, originalVolume })}
                disabled={!canControlOriginal}
                hint={canControlOriginal ? L.originalHint : L.originalFixed}
              />
              <Slider label={L.dubVolume} value={settings.dubVolume} onChange={(dubVolume) => onSettingsChange({ ...settings, dubVolume })} />
            </div>
          )}

          <p className="text-xs leading-relaxed text-ink-400">{L.costNote}</p>
        </>
      )}
    </section>
  );
}

function Slider({
  label,
  value,
  onChange,
  disabled = false,
  hint,
}: {
  label: string;
  value: number;
  onChange: (v: number) => void;
  disabled?: boolean;
  hint?: string;
}) {
  const id = useId();
  const pct = Math.round(value * 100);
  return (
    <div className="space-y-1.5">
      <div className="flex items-center justify-between text-xs">
        <label htmlFor={id} className="text-ink-300">
          {label}
        </label>
        <span className="text-ink-400 tabular-nums">{pct}%</span>
      </div>
      <input
        id={id}
        type="range"
        min={0}
        max={100}
        step={5}
        value={pct}
        disabled={disabled}
        onChange={(e) => onChange(Number(e.target.value) / 100)}
        className="w-full accent-[var(--color-accent)] disabled:opacity-40"
      />
      {hint && <p className="text-[11px] leading-snug text-ink-500">{hint}</p>}
    </div>
  );
}

