    this.interim = null;
    if (alt.words && alt.words.length > 0) {
      for (const w of alt.words) {
        const start = offset + w.start;
        if (start < this.finalizedUntil - 0.02) continue; // already have it (replay / duplicate)
        this.pending.push({ text: w.punctuated_word ?? w.word, start, end: offset + w.end, language: w.language });
      }
    } else if (alt.transcript.trim() && segEnd > this.finalizedUntil + 0.01) {
      this.pending.push({ text: alt.transcript.trim(), start: segStart, end: segEnd, language: alt.languages?.[0] });
    }
    this.finalizedUntil = Math.max(this.finalizedUntil, segEnd);

    if (msg.speech_final) this.commit();
    else this.splitLongLine();
    this.emitCaption();
  }

  /** Deepgram `UtteranceEnd`: the speaker paused, close the current line. */
  handleUtteranceEnd(): void {
    this.commit();
    this.emitCaption();
  }

  /** Commit what we have (stop, seek, pause). Interim text is discarded because it was never confirmed. */
  flush(opts: { clearCaption?: boolean } = {}): void {
    this.commit();
    this.interim = null;
    if (opts.clearCaption) this.emit({ type: "caption", caption: { ...EMPTY_CAPTION, updatedAt: this.opts.now() } });
    else this.emitCaption();
  }

  /**
   * Continuous speech may never produce `speech_final`. Once the pending text is long,
   * commit up to the last sentence boundary (or everything past the hard limit) so the
   * transcript stays readable and timestamps stay useful.
   */
  private splitLongLine(): void {
    while (pendingLength(this.pending) >= this.opts.softLineLimit) {
      let chars = 0;
      let cut = -1;
      for (let i = 0; i < this.pending.length; i++) {
        chars += this.pending[i]!.text.length + 1;
        if (chars >= 40 && /[.!?]["')\]]?$/.test(this.pending[i]!.text)) cut = i;
      }
      if (cut < 0) {
        if (pendingLength(this.pending) >= this.opts.hardLineLimit) this.commit();
        return;
      }
      this.commit(cut + 1);
    }
  }

  private commit(count = this.pending.length): void {
    const words = this.pending.slice(0, count);
    this.pending = this.pending.slice(count);
    const text = words.map((w) => w.text).join(" ").trim();
    if (!text) return;
    const start = words[0]!.start;
    const end = words[words.length - 1]!.end;
    const media = this.opts.mediaTimeAt;
    const mediaStart = media ? media(start) : null;
    const mediaEnd = media ? media(end) : null;
    const language = mainLanguage(words);
    this.lastCommitted = text;
    this.lastCommittedLanguage = language;
    this.emit({
      type: "line",
      line: {
        id: `${this.opts.idPrefix}-${++this.counter}`,
        text,
        start: round(start),
        end: round(end),
        mediaStart: mediaStart === null ? null : round(mediaStart),
        mediaEnd: mediaEnd === null ? null : round(mediaEnd),
        createdAt: this.opts.now(),
        ...(language ? { language } : {}),
      },
    });
  }

  private lastCommitted = "";
  private lastCommittedLanguage: string | undefined;

  private emitCaption(): void {
    const pendingText = this.pending.map((w) => w.text).join(" ");
    const parts = [pendingText, this.interim?.text].filter(Boolean) as string[];
    // Between utterances keep showing the last line until the renderer fades it.
    const text = parts.length > 0 ? parts.join(" ") : this.lastCommitted;
    const language =
      parts.length > 0 ? mainLanguage(this.interim ? [...this.pending, this.interim] : this.pending) : this.lastCommittedLanguage;
    this.emit({
      type: "caption",
      caption: {
        text: tail(text, this.opts.captionChars),
        hasInterim: Boolean(this.interim),
        updatedAt: this.opts.now(),
        ...(language ? { language } : {}),
      },
    });
  }
}

/** Keep the last `max` characters, cut at a word boundary. */
export function tail(text: string, max: number): string {
  if (text.length <= max) return text;
  const cut = text.slice(text.length - max);
  const space = cut.indexOf(" ");
  return space >= 0 ? cut.slice(space + 1) : cut;
}

/** The language most of these spans are in (by characters), if Deepgram reported any. */
function mainLanguage(spans: Span[]): string | undefined {
  const counts = new Map<string, number>();
  for (const s of spans) if (s.language) counts.set(s.language, (counts.get(s.language) ?? 0) + s.text.length);
  let best: string | undefined;
  let n = 0;
  for (const [lang, c] of counts) if (c > n) [best, n] = [lang, c];
  return best;
}

function pendingLength(words: Span[]): number {
  return words.reduce((n, w) => n + w.text.length + 1, 0);
}

function round(n: number) {
  return Math.round(n * 1000) / 1000;
}

import { PCM_TARGET_SAMPLE_RATE } from "./audio";
import type { DeepgramCredential, DeepgramStreamOptions } from "./types";
import type { DgResults } from "./transcript";

export const DEEPGRAM_LISTEN_URL = "wss://api.deepgram.com/v1/listen";

/** Build the Nova-3 streaming URL for 16 kHz mono linear16 audio. */
export function buildListenUrl(opts: DeepgramStreamOptions = {}, base = DEEPGRAM_LISTEN_URL): string {
  const p = new URLSearchParams({
    model: opts.model ?? "nova-3",
    language: opts.language ?? "en",
    encoding: "linear16",
    sample_rate: String(PCM_TARGET_SAMPLE_RATE),
    channels: "1",
    interim_results: "true",
    smart_format: "true",
    endpointing: "300",
    utterance_end_ms: "1000",
    vad_events: "true",
  });
  for (const term of opts.keyterms ?? []) if (term.trim()) p.append("keyterm", term.trim());
  return `${base}?${p.toString()}`;
}

export type DeepgramServerMessage =
  | DgResults
  | { type: "UtteranceEnd"; last_word_end?: number }
  | { type: "SpeechStarted"; timestamp?: number }
  | { type: "Metadata"; request_id?: string }
  | { type: "Error" | "Warning"; description?: string; message?: string; code?: string; err_code?: string }
  | { type: string; [k: string]: unknown };

export interface DeepgramSocketHandlers {
  onOpen: () => void;
  onMessage: (msg: DeepgramServerMessage) => void;
  onClose: (info: { code: number; reason: string; wasOpen: boolean }) => void;
}

/**
 * Thin wrapper around a browser WebSocket to Deepgram's /v1/listen.
 *
 * Browsers cannot set an Authorization header on WebSockets, so credentials go in the
 * subprotocol — the same mechanism the official @deepgram/sdk uses in the browser:
 * `["bearer", jwt]` for server-minted tokens, `["token", apiKey]` for a user's own key.
 */
export class DeepgramSocket {
  private ws: WebSocket;
  private opened = false;
  private closedByUs = false;

  constructor(credential: DeepgramCredential, url: string, private readonly handlers: DeepgramSocketHandlers) {
    this.ws = new WebSocket(url, [credential.type, credential.value]);
    this.ws.binaryType = "arraybuffer";
    this.ws.onopen = () => {
      this.opened = true;
      handlers.onOpen();
    };
    this.ws.onmessage = (e) => {
      if (typeof e.data !== "string") return;
      try {
        handlers.onMessage(JSON.parse(e.data) as DeepgramServerMessage);
      } catch {
        /* ignore malformed frames */
      }
    };
    this.ws.onclose = (e) => handlers.onClose({ code: e.code, reason: e.reason, wasOpen: this.opened });
    this.ws.onerror = () => {
      /* onclose always follows with details */
    };
  }

  get isOpen(): boolean {
    return this.ws.readyState === WebSocket.OPEN;
  }

  get isClosedByUs(): boolean {
    return this.closedByUs;
  }

  sendAudio(pcm: ArrayBuffer): boolean {
    if (!this.isOpen) return false;
    this.ws.send(pcm);
    return true;
  }

  /** Control messages must be text frames. */
  private control(type: "KeepAlive" | "Finalize" | "CloseStream") {
    if (this.isOpen) this.ws.send(JSON.stringify({ type }));
  }

  keepAlive() {
    this.control("KeepAlive");
  }

  /** Flush the current partial as a final result without closing. */
  finalize() {
    this.control("Finalize");
  }

  /** Ask Deepgram to flush and close; resolves once closed (or after a timeout). */
  async closeGracefully(timeoutMs = 5000): Promise<void> {
    this.closedByUs = true;
    if (this.ws.readyState === WebSocket.CLOSED) return;
    if (this.ws.readyState === WebSocket.CONNECTING) {
      this.ws.close();
      return;
    }
    await new Promise<void>((resolve) => {
      const timer = setTimeout(() => {
        this.ws.close(1000);
        resolve();
      }, timeoutMs);
      this.ws.addEventListener("close", () => {
        clearTimeout(timer);
        resolve();
      });
      this.control("CloseStream");
    });
  }

  abort() {
    this.closedByUs = true;
    try {
      this.ws.close(1000);
    } catch {
      /* noop */
    }
  }
}

/** Human-readable explanation for a socket close. */
export function describeClose(code: number, reason: string, wasOpen: boolean): string {
  if (reason) return `Deepgram closed the connection: ${reason}`;
  if (!wasOpen) return "Could not connect to Deepgram. Check your network connection.";
  if (code === 1008) return "Deepgram rejected the stream (policy violation).";
  if (code === 1011) return "Deepgram timed out waiting for audio.";
  return `Connection to Deepgram lost (code ${code}).`;
}

/** Cheap shape check for a pasted Deepgram API key (they are 40 hex characters today). */
export function looksLikeDeepgramKey(key: string): boolean {
  return /^[A-Za-z0-9_-]{32,128}$/.test(key.trim());
}

export type KeyCheckResult = "ok" | "rejected" | "offline";

/**
 * Verify a user's Deepgram key from the browser by briefly opening a streaming socket.
 * (Deepgram's REST API doesn't allow browser CORS, so the socket is the only browser-side check.)
 * A rejected key fails the handshake with HTTP 401, which browsers surface as a close before open.
 */
export function verifyDeepgramKey(key: string, timeoutMs = 8000): Promise<KeyCheckResult> {
  return new Promise((resolve) => {
    if (typeof navigator !== "undefined" && navigator.onLine === false) return resolve("offline");
    let done = false;
    const finish = (r: KeyCheckResult) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      resolve(r);
    };
    let ws: WebSocket;
    try {
      ws = new WebSocket(buildListenUrl(), ["token", key.trim()]);
    } catch {
      return resolve("rejected");
    }
    const timer = setTimeout(() => {
      try {
        ws.close();
      } catch {
        /* noop */
      }
      finish("offline");
    }, timeoutMs);
    ws.onopen = () => {
      ws.send(JSON.stringify({ type: "CloseStream" }));
      ws.close(1000);
      finish("ok");
    };
    ws.onerror = () => finish(typeof navigator !== "undefined" && navigator.onLine === false ? "offline" : "rejected");
    ws.onclose = () => finish("rejected");
  });
}
/**
 * Tab audio → 16 kHz mono linear16 PCM chunks, using an AudioWorklet.
 *
 * The worklet source is exported as a string so each surface can load it the way its
 * Content-Security-Policy allows: the web app uses a Blob URL (`createPcmWorkletUrl`),
 * the extension ships it as a packaged file (`chrome.runtime.getURL("pcm-worklet.js")`).
 */

export const PCM_TARGET_SAMPLE_RATE = 16000;
export const PCM_WORKLET_NAME = "heard-pcm";

export const PCM_WORKLET_SOURCE = /* js */ `
class HeardPcmProcessor extends AudioWorkletProcessor {
  constructor(options) {
    super();
    const o = (options && options.processorOptions) || {};
    this.ratio = sampleRate / (o.targetSampleRate || 16000);
    this.pos = 0;
    this.prev = 0;
    this.size = o.chunkSamples || 1600;
    this.chunk = new Int16Array(this.size);
    this.idx = 0;
  }
  process(inputs) {
    const input = inputs[0];
    if (!input || input.length === 0 || !input[0]) return true;
    const n = input[0].length;
    const channels = input.length;
    const mono = new Float32Array(n);
    for (let c = 0; c < channels; c++) {
      const data = input[c];
      for (let i = 0; i < n; i++) mono[i] += data[i] / channels;
    }
    // Linear-interpolation resampler; position carries across render quanta.
    while (this.pos < n - 1) {
      const i0 = Math.floor(this.pos);
      const f = this.pos - i0;
      const a = i0 < 0 ? this.prev : mono[i0];
      const b = mono[i0 + 1];
      let v = a + (b - a) * f;
      v = v < -1 ? -1 : v > 1 ? 1 : v;
      this.chunk[this.idx++] = v < 0 ? v * 0x8000 : v * 0x7fff;
      if (this.idx === this.size) {
        this.port.postMessage(this.chunk.buffer, [this.chunk.buffer]);
        this.chunk = new Int16Array(this.size);
        this.idx = 0;
      }
      this.pos += this.ratio;
    }
    this.pos -= n;
    this.prev = mono[n - 1];
    return true;
  }
}
registerProcessor("${PCM_WORKLET_NAME}", HeardPcmProcessor);
`;

/** Blob URL for the worklet (works where CSP allows blob: scripts, e.g. the web app). */
export function createPcmWorkletUrl(): string {
  return URL.createObjectURL(new Blob([PCM_WORKLET_SOURCE], { type: "application/javascript" }));
}

export interface PcmCaptureOptions {
  stream: MediaStream;
  workletUrl: string;
  /** Route captured audio back to the speakers (needed for chrome.tabCapture, which mutes the tab). */
  preservePlayback?: boolean;
  /** Chunk length in ms. Deepgram recommends 20–250 ms. */
  chunkMs?: number;
  onChunk: (pcm: ArrayBuffer) => void;
  /** Called when the captured track ends (user clicked "Stop sharing", tab closed, ...). */
  onEnded?: () => void;
}

export interface PcmCapture {
  readonly sampleRate: number;
  /**
   * Level of the audio routed back to the speakers (preservePlayback), 0..1. Only the
   * speakers change: the transcription tap always gets the full-level signal.
   */
  setPlaybackVolume(volume: number): void;
  stop(): Promise<void>;
}

export async function startPcmCapture(opts: PcmCaptureOptions): Promise<PcmCapture> {
  const track = opts.stream.getAudioTracks()[0];
  if (!track) throw new Error("The captured stream has no audio track. Make sure “Share tab audio” is enabled.");

  const ctx = new AudioContext({ latencyHint: "interactive" });
  try {
    await ctx.audioWorklet.addModule(opts.workletUrl);
  } catch (err) {
    await ctx.close();
    throw new Error(`Could not load the audio processor: ${(err as Error).message}`);
  }
  const source = ctx.createMediaStreamSource(opts.stream);
  const chunkSamples = Math.round((PCM_TARGET_SAMPLE_RATE * (opts.chunkMs ?? 100)) / 1000);
  const node = new AudioWorkletNode(ctx, PCM_WORKLET_NAME, {
    numberOfInputs: 1,
    numberOfOutputs: 1,
    channelCountMode: "max",
    processorOptions: { targetSampleRate: PCM_TARGET_SAMPLE_RATE, chunkSamples },
  });
  node.port.onmessage = (e: MessageEvent<ArrayBuffer>) => opts.onChunk(e.data);

  // Keep the worklet pulled by the graph without making it audible.
  const sink = ctx.createGain();
  sink.gain.value = 0;
  source.connect(node);
  node.connect(sink);
  sink.connect(ctx.destination);
  // Speakers get their own gain node so the user can turn the original down (e.g. while
  // dubbing) without the worklet hearing any less.
  const playback = opts.preservePlayback ? ctx.createGain() : null;
  if (playback) {
    source.connect(playback);
    playback.connect(ctx.destination);
  }

  const onEnded = () => opts.onEnded?.();
  track.addEventListener("ended", onEnded);
  if (ctx.state === "suspended") await ctx.resume().catch(() => undefined);

  let stopped = false;
  return {
    sampleRate: PCM_TARGET_SAMPLE_RATE,
    setPlaybackVolume(volume: number) {
      if (!playback) return;
      const v = Number.isFinite(volume) ? Math.min(1, Math.max(0, volume)) : 1;
      // A short ramp avoids clicks when ducking.
      playback.gain.setTargetAtTime(v, ctx.currentTime, 0.03);
    },
    async stop() {
      if (stopped) return;
      stopped = true;
      track.removeEventListener("ended", onEnded);
      node.port.onmessage = null;
      try {
        source.disconnect();
        node.disconnect();
        sink.disconnect();
        playback?.disconnect();
      } catch {
        /* already disconnected */
      }
      await ctx.close().catch(() => undefined);
    },
  };
}

/** Stop every track of a stream (releases the "sharing this tab" indicator). */
export function stopStream(stream: MediaStream | null | undefined): void {
  stream?.getTracks().forEach((t) => t.stop());
}
import { startPcmCapture, stopStream, PCM_TARGET_SAMPLE_RATE, type PcmCapture } from "./audio";
import { buildListenUrl, describeClose, DeepgramSocket, type DeepgramServerMessage } from "./deepgram";
import { AUTO_LANGUAGE } from "./settings";
import { StreamTimeMap } from "./time-map";
import { TranslationEngine } from "./translate";
import { initialTranscriptState, reduceTranscript, TranscriptAssembler, type DgResults } from "./transcript";
import type { DeepgramCredential, DeepgramStreamOptions, TranscriptEvent, TranscriptState, TranscriptionStatus } from "./types";

/** Throw this from `getToken` when retrying cannot help (e.g. server has no API key). */
export class FatalTranscriptionError extends Error {
  readonly fatal = true;
}

export interface TranscriptionSessionOptions {
  /**
   * Returns the credential for each (re)connect: a short-lived JWT from a Heard server
   * (a plain string is treated as a bearer JWT) or the user's own key (`{ type: "token" }`).
   */
  getToken: () => Promise<string | DeepgramCredential>;
  /** URL of the PCM AudioWorklet module (see PCM_WORKLET_SOURCE). */
  workletUrl: string;
  /** Re-route captured audio to the speakers (chrome.tabCapture mutes the tab otherwise). */
  preservePlayback?: boolean;
  /** Current media position (e.g. video currentTime) or null. Enables seekable timestamps. */
  getMediaTime?: () => number | null;
  deepgram?: DeepgramStreamOptions;
  /** Override for tests / regional endpoints. */
  listenBaseUrl?: string;
  /** Called with every transcript event (for forwarding across processes). */
  onEvent?: (event: TranscriptEvent) => void;
  maxReconnectAttempts?: number;
}

const KEEPALIVE_MS = 3000;
const MAX_BUFFER_SECONDS = 15;

interface BufferedChunk {
  pcm: ArrayBuffer;
  start: number;
}

/**
 * Owns one transcription run: audio capture → Deepgram socket → transcript assembly.
 * Provider-agnostic: give it any MediaStream with an audio track.
 */
export class TranscriptionSession {
  private state: TranscriptState = initialTranscriptState();
  private listeners = new Set<(s: TranscriptState) => void>();
  private assembler: TranscriptAssembler;
  private timeMap = new StreamTimeMap();

  private stream: MediaStream | null = null;
  private ownsStream = true;
  private capture: PcmCapture | null = null;
  private socket: DeepgramSocket | null = null;
  /** Absolute stream time of the first chunk sent on the current socket. */
  private connOffset: number | null = null;
  private streamSeconds = 0;
  private buffer: BufferedChunk[] = [];
  private gated = false;
  private running = false;
  private attempts = 0;
  /** Whether any socket opened during this run (a user key that never opens is likely invalid). */
  private everOpened = false;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  /** Deepgram language code, or "multi" to detect it. */
  private spokenLanguage = AUTO_LANGUAGE;
  private readonly translation = new TranslationEngine((e) => this.dispatch(e));
  private keepAliveTimer: ReturnType<typeof setInterval> | null = null;
  private playbackVolume = 1;
  private lastSentAt = 0;
  private readonly onOnline = () => {
    if (this.running && !this.socket && this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
      void this.connect();
    }
  };

  constructor(private readonly opts: TranscriptionSessionOptions) {
    this.assembler = this.createAssembler();
  }

  /* ----------------------------- public API ----------------------------- */

  getState(): TranscriptState {
    return this.state;
  }

  subscribe(listener: (s: TranscriptState) => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  get isRunning(): boolean {
    return this.running;
  }

  /**
   * What's spoken (a Deepgram code, or "multi" to detect it) and what the captions should be
   * in ("" for the spoken language). A new spoken language reconnects to Deepgram, buffering
   * the audio in between; a new caption language translates from the next words on.
   */
  setLanguages(spoken: string, caption: string): void {
    this.translation.configure(spoken, caption);
    const next = spoken || AUTO_LANGUAGE;
    if (next === this.spokenLanguage) return;
    this.spokenLanguage = next;
    if (this.running && this.socket) void this.reconnectNow();
  }

  /**
   * Start transcribing `stream`. If `ownsStream` (default) the stream's tracks are stopped
   * when the session stops.
   */
  async start(stream: MediaStream, { ownsStream = true, keepTranscript = false } = {}): Promise<void> {
    if (this.running) await this.stop();
    this.running = true;
    this.stream = stream;
    this.ownsStream = ownsStream;
    this.streamSeconds = 0;
    this.buffer = [];
    this.gated = false;
    this.attempts = 0;
    this.everOpened = false;
    this.timeMap.clear();
    this.assembler = this.createAssembler();
    if (keepTranscript) {
      this.dispatch({ type: "snapshot", state: { ...this.state, startedAt: this.state.startedAt ?? Date.now() } });
    } else {
      this.dispatch({ type: "reset", startedAt: Date.now() });
    }
    this.setStatus("connecting");

    try {
      this.capture = await startPcmCapture({
        stream,
        workletUrl: this.opts.workletUrl,
        preservePlayback: this.opts.preservePlayback,
        onChunk: (pcm) => this.onChunk(pcm),
        onEnded: () => void this.stop("Audio capture ended."),
      });
      this.capture.setPlaybackVolume?.(this.playbackVolume);
    } catch (err) {
      await this.fail((err as Error).message);
      return;
    }

    if (typeof window !== "undefined") window.addEventListener("online", this.onOnline);
    this.keepAliveTimer = setInterval(() => {
      if (this.socket?.isOpen && Date.now() - this.lastSentAt >= KEEPALIVE_MS) this.socket.keepAlive();
    }, 1000);

    await this.connect();
  }

  /**
   * Pause/resume streaming (e.g. when the video is paused). While paused no audio is
   * sent — the socket is kept alive with KeepAlive messages — so silence isn't billed.
   */
  setPaused(paused: boolean): void {
    if (!this.running || this.gated === paused) return;
    this.gated = paused;
    if (paused) {
      this.socket?.finalize();
      this.setStatus("paused");
    } else if (this.socket?.isOpen) {
      this.setStatus("live");
    }
  }

  /**
   * Speaker level of the original audio when `preservePlayback` is on (0..1). Transcription
   * is unaffected: it reads the captured stream before this gain.
   */
  setPlaybackVolume(volume: number): void {
    this.playbackVolume = volume;
    this.capture?.setPlaybackVolume?.(volume);
  }

  /** The media jumped (seek). Flush pending text and clear the on-screen caption. */
  markDiscontinuity(): void {
    if (!this.running) return;
    this.socket?.finalize();
    this.assembler.flush({ clearCaption: true });
  }

  /** Stop capture and close the socket after Deepgram flushes final results. */
  async stop(errorMessage?: string): Promise<void> {
    if (!this.running) return;
    this.running = false;
    this.clearTimers();
    if (typeof window !== "undefined") window.removeEventListener("online", this.onOnline);

    const capture = this.capture;
    this.capture = null;
    await capture?.stop();

    const socket = this.socket;
    this.socket = null;
    if (socket) {
      // Keep processing messages that arrive while closing (final words).
      await socket.closeGracefully();
    }
    this.assembler.flush();
    this.buffer = [];
    if (this.ownsStream) stopStream(this.stream);
    this.stream = null;
    if (errorMessage) this.setStatus("error", errorMessage);
    else this.setStatus("idle");
  }

  /** Clear transcript lines (only while stopped). */
  clear(): void {
    if (this.running) return;
    this.dispatch({ type: "reset", startedAt: null });
  }

  /* ----------------------------- internals ----------------------------- */

  private createAssembler() {
    return new TranscriptAssembler((e) => this.dispatch(e), {
      mediaTimeAt: this.opts.getMediaTime ? (t) => this.timeMap.mediaAt(t) : undefined,
    });
  }

  private dispatch(event: TranscriptEvent) {
    this.state = reduceTranscript(this.state, event);
    this.opts.onEvent?.(event);
    for (const l of this.listeners) l(this.state);
    this.translation.handle(event);
  }

  /** Close the socket (keeping its last words) and open a new one with the current options. */
  private async reconnectNow() {
    const old = this.socket;
    this.socket = null; // audio buffers until the new socket opens
    if (old) await old.closeGracefully(2000);
    this.assembler.flush();
    if (!this.running || this.socket) return;
    this.attempts = 0;
    await this.connect();
  }

  private setStatus(status: TranscriptionStatus, error: string | null = null) {
    if (this.state.status === status && this.state.error === error) return;
    this.dispatch({ type: "status", status, error });
  }

  private onChunk(pcm: ArrayBuffer) {
    if (!this.running || this.gated) return;
    const start = this.streamSeconds;
    this.streamSeconds += pcm.byteLength / 2 / PCM_TARGET_SAMPLE_RATE;
    let media: number | null = null;
    try {
      media = this.opts.getMediaTime?.() ?? null;
    } catch {
      media = null;
    }
    this.timeMap.record(this.streamSeconds, media);

    if (this.socket?.isOpen) {
      this.send({ pcm, start });
    } else {
      this.buffer.push({ pcm, start });
      // Keep only the most recent contiguous audio while disconnected.
      while (this.buffer.length > 0 && this.streamSeconds - this.buffer[0]!.start > MAX_BUFFER_SECONDS) {
        this.buffer.shift();
      }
    }
  }

  private send(chunk: BufferedChunk) {
    if (!this.socket) return;
    if (this.connOffset === null) this.connOffset = chunk.start;
    if (this.socket.sendAudio(chunk.pcm)) this.lastSentAt = Date.now();
  }

  private async connect(): Promise<void> {
    if (!this.running) return;
    this.setStatus(this.attempts === 0 ? "connecting" : "reconnecting");

    let credential: DeepgramCredential;
    try {
      const token = await this.opts.getToken();
      credential = typeof token === "string" ? { type: "bearer", value: token } : token;
    } catch (err) {
      if ((err as FatalTranscriptionError).fatal) return this.fail((err as Error).message);
      return this.scheduleReconnect((err as Error).message);
    }
    if (!this.running) return;

    this.connOffset = null;
    const url = buildListenUrl({ ...this.opts.deepgram, language: this.spokenLanguage }, this.opts.listenBaseUrl);
    const socket = new DeepgramSocket(credential, url, {
      onOpen: () => {
        if (this.socket !== socket) return;
        this.everOpened = true;
        this.setStatus(this.gated ? "paused" : "live");
        const pending = this.buffer;
        this.buffer = [];
        for (const chunk of pending) this.send(chunk);
      },
      onMessage: (msg) => {
        if (this.socket !== socket && !socket.isClosedByUs) return;
        this.handleMessage(msg);
      },
      onClose: ({ code, reason, wasOpen }) => {
        if (socket.isClosedByUs || this.socket !== socket) return;
        this.socket = null;
        this.assembler.flush();
        if (wasOpen) this.attempts = 0;
        if (!wasOpen && !this.everOpened && credential.type === "token" && !(typeof navigator !== "undefined" && navigator.onLine === false)) {
          void this.fail("Deepgram didn't accept your API key. Check it in settings, or create a new one at console.deepgram.com.");
          return;
        }
        this.scheduleReconnect(describeClose(code, reason, wasOpen));
      },
    });
    this.socket = socket;
  }

  private connOffsetValue() {
    return this.connOffset ?? 0;
  }

  private handleMessage(msg: DeepgramServerMessage) {
    switch (msg.type) {
      case "Results":
        this.assembler.handleResults(msg as DgResults, this.connOffsetValue());
        if (this.attempts > 0) this.attempts = 0;
        break;
      case "UtteranceEnd":
        this.assembler.handleUtteranceEnd();
        break;
      default:
        break;
    }
  }

  private scheduleReconnect(reason: string) {
    if (!this.running) return;
    this.attempts += 1;
    const max = this.opts.maxReconnectAttempts ?? 6;
    if (this.attempts > max) {
      void this.fail(`${reason} Gave up after ${max} attempts.`);
      return;
    }
    this.setStatus("reconnecting", reason);
    const delay = Math.min(500 * 2 ** (this.attempts - 1), 8000);
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      void this.connect();
    }, delay);
  }

  private async fail(message: string) {
    await this.stop(message);
    if (this.state.status !== "error") this.setStatus("error", message);
  }

  private clearTimers() {
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    if (this.keepAliveTimer) clearInterval(this.keepAliveTimer);
    this.reconnectTimer = null;
    this.keepAliveTimer = null;
  }
}

/**
 * - `off`: dubbing is disabled.
 * - `connecting`: opening the Flux TTS socket.
 * - `listening`: ready, waiting for the next finished phrase.
 * - `translating`: a phrase is being translated.
 * - `playing`: dubbed speech is coming out of the speakers.
 * - `reconnecting`: the TTS socket dropped; retrying.
 * - `unavailable`: dubbing can't run (bad key, repeated failures, unsupported capture);
 *   original audio is restored and `error` says why.
 */
export type DubStatus = "off" | "connecting" | "listening" | "translating" | "playing" | "reconnecting" | "unavailable";

export interface DubState {
  status: DubStatus;
  /** Why dubbing is unavailable or reconnecting (English, from the shared code). */
  error: string | null;
  /**
   * How far the dubbed speech trails the original, in ms: from the moment a phrase was
   * finalized by speech-to-text to the moment its dubbed audio started playing. Null until measured.
   */
  delayMs: number | null;
  /** Phrases skipped to stay close to live (since dubbing was enabled). */
  skipped: number;
}

export const INITIAL_DUB_STATE: DubState = { status: "off", error: null, delayMs: null, skipped: 0 };

/** A finished, translated phrase on its way to speech synthesis. */
export interface DubSegment {
  /** Increasing per pipeline; used to keep order and drop duplicates. */
  seq: number;
  text: string;
  /** Wall-clock ms when the original words were finalized (the delay measurement's start). */
  spokenAt: number;
}
/**
 * Front half of live dubbing: finalized transcript lines → natural phrases → translated text,
 * in the order they were spoken. Interim results are never used, so the dub never repeats or
 * corrects itself.
 *
 * Runs wherever Chrome's translator works (the extension's side panel, a web page). The
 * translated phrases go to a DubOutput, which may live in another context.
 */
import { AUTO_LANGUAGE } from "../settings";
import { translateText } from "../translate";
import type { TranscriptEvent, TranscriptLine, TranslationIssue } from "../types";
import type { DubSegment } from "./types";

export interface PhraseOptions {
  /** Wait this long for a short fragment's continuation before sending it alone. */
  holdMs?: number;
  /** Never hold a phrase longer than this since its first words were finalized. */
  maxHoldMs?: number;
  /** Phrases older than this when they're ready to speak are skipped (stay close to live). */
  maxLagMs?: number;
  /** Injected for tests. */
  translate?: typeof translateText;
  now?: () => number;
}

export interface PhraseHandlers {
  onSegment: (segment: DubSegment) => void;
  /** True while at least one phrase is being translated. */
  onTranslating?: (busy: boolean) => void;
  /** A phrase couldn't be translated (null clears). */
  onIssue?: (issue: TranslationIssue | null) => void;
  /** A phrase was dropped because it got too old. */
  onSkipped?: () => void;
}

interface Pending {
  text: string;
  spokenAt: number;
  firstAt: number;
  language: string | undefined;
}

const SENTENCE_END = /[.!?。！？…]["'”’)\]]*$/u;
/** Scripts written without spaces: count characters instead of words. */
const NO_SPACES = /[぀-ヿ㐀-鿿가-힯]/u;

function size(text: string): number {
  return NO_SPACES.test(text) ? Math.ceil(text.replace(/\s/g, "").length / 3) : text.split(/\s+/).filter(Boolean).length;
}

/** Whether a phrase is ready to speak without waiting for more words. */
export function isCompletePhrase(text: string): boolean {
  const n = size(text);
  return n >= 12 || (n >= 3 && SENTENCE_END.test(text.trim()));
}

export class DubPhrasePipeline {
  private spoken = AUTO_LANGUAGE;
  private target = "";
  private active = false;
  private since = 0;
  private generation = 0;
  private seq = 0;
  private seen = new Set<string>();
  private pending: Pending | null = null;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private chain: Promise<void> = Promise.resolve();
  private inFlight = 0;
  private readonly holdMs: number;
  private readonly maxHoldMs: number;
  private readonly maxLagMs: number;
  private readonly translate: typeof translateText;
  private readonly now: () => number;

  constructor(
    private readonly handlers: PhraseHandlers,
    opts: PhraseOptions = {},
  ) {
    this.holdMs = opts.holdMs ?? 900;
    this.maxHoldMs = opts.maxHoldMs ?? 2000;
    this.maxLagMs = opts.maxLagMs ?? 8000;
    this.translate = opts.translate ?? translateText;
    this.now = opts.now ?? Date.now;
  }

  /** `spoken`: Deepgram code or "multi". `target`: translator code of the dubbed speech. */
  configure(spoken: string, target: string): void {
    const s = spoken || AUTO_LANGUAGE;
    if (s === this.spoken && target === this.target) return;
    this.spoken = s;
    this.target = target;
    // A new language makes everything in flight outdated.
    this.clear();
  }

  /** Start dubbing from now on: lines finalized before this call are never spoken. */
  start(): void {
    if (this.active) return;
    this.active = true;
    this.since = this.now();
    this.clear();
  }

  stop(): void {
    this.active = false;
    this.clear();
  }

  get isActive(): boolean {
    return this.active;
  }

  /** Drop held and in-flight phrases (seek, language change, new video). */
  clear(): void {
    this.generation += 1;
    this.pending = null;
    if (this.timer) clearTimeout(this.timer);
    this.timer = null;
    this.chain = Promise.resolve();
    if (this.inFlight > 0) {
      this.inFlight = 0;
      this.handlers.onTranslating?.(false);
    }
  }

  /** Feed every transcript event. */
  handle(event: TranscriptEvent): void {
    if (event.type === "reset") {
      this.seen.clear();
      this.clear();
      return;
    }
    if (event.type !== "line" || !this.active || !this.target) return;
    this.addLine(event.line);
  }

  private addLine(line: TranscriptLine) {
    if (this.seen.has(line.id)) return;
    this.seen.add(line.id);
    if (line.createdAt < this.since) return;
    const text = line.text.trim();
    if (!text) return;

    const p = this.pending;
    // A language switch ends the phrase: each one is translated from its own language.
    if (p && p.language !== line.language) this.emit();
    if (this.pending) {
      this.pending.text = `${this.pending.text} ${text}`;
      this.pending.spokenAt = line.createdAt;
      this.pending.language ??= line.language;
    } else {
      this.pending = { text, spokenAt: line.createdAt, firstAt: line.createdAt, language: line.language };
    }

    const cur = this.pending!;
    if (isCompletePhrase(cur.text) || this.now() - cur.firstAt >= this.maxHoldMs) {
      this.emit();
      return;
    }
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      this.timer = null;
      this.emit();
    }, this.holdMs);
  }

  private sourceFor(detected: string | undefined): string | null {
    return this.spoken === AUTO_LANGUAGE ? (detected ?? null) : this.spoken;
  }

  private emit() {
    const p = this.pending;
    this.pending = null;
    if (this.timer) clearTimeout(this.timer);
    this.timer = null;
    if (!p) return;

    const generation = this.generation;
    const target = this.target;
    const source = this.sourceFor(p.language);
    const seq = ++this.seq;
    // Translations run in parallel but are released in spoken order.
    this.setBusy(+1);
    const translated = source
      ? this.translate(p.text, source, target).catch(
          (err): Awaited<ReturnType<typeof translateText>> => ({
            ok: false,
            issue: { source, target, kind: "failed", detail: String(err) },
          }),
        )
      : Promise.resolve<Awaited<ReturnType<typeof translateText>>>({
          ok: false,
          issue: { source: "", target, kind: "unsupported" },
        });

    this.chain = this.chain.then(async () => {
      const result = await translated;
      if (generation !== this.generation) return;
      this.setBusy(-1);
      if (!result.ok) {
        this.handlers.onIssue?.(result.issue);
        return;
      }
      this.handlers.onIssue?.(null);
      if (this.now() - p.spokenAt > this.maxLagMs) {
        this.handlers.onSkipped?.();
        return;
      }
      const text = result.text.trim();
      if (text) this.handlers.onSegment({ seq, text, spokenAt: p.spokenAt });
    });
  }

  private setBusy(delta: number) {
    const before = this.inFlight;
    this.inFlight = Math.max(0, this.inFlight + delta);
    if ((before === 0) !== (this.inFlight === 0)) this.handlers.onTranslating?.(this.inFlight > 0);
  }
}
/**
 * Back half of live dubbing: translated phrases → Flux TTS → playback queue, plus the
 * status the UI shows. Runs in a context whose audio is NOT being captured (the extension's
 * offscreen document), so the dub is never transcribed again.
 */
import type { DeepgramCredential } from "../types";
import { FluxSpeaker, type SpeakerStatus } from "./flux-tts";
import { DubPlayer, type DubAudioContext } from "./player";
import { INITIAL_DUB_STATE, type DubSegment, type DubState } from "./types";

export interface DubOutputOptions {
  getToken: () => Promise<string | DeepgramCredential>;
  onState?: (state: DubState) => void;
  /** Livestreams should stay closer to live than recorded videos. */
  maxLagMs?: number;
  speakBaseUrl?: string;
  createContext?: () => DubAudioContext;
  WebSocketImpl?: typeof WebSocket;
}

export class DubOutput {
  private state: DubState = INITIAL_DUB_STATE;
  private speaker: FluxSpeaker | null = null;
  private speakerStatus: SpeakerStatus = "idle";
  private speakerError: string | null = null;
  private translating = false;
  private playing = false;
  private lastSeq = 0;
  private readonly player: DubPlayer;

  constructor(private readonly opts: DubOutputOptions) {
    this.player = new DubPlayer({
      maxLagMs: opts.maxLagMs,
      createContext: opts.createContext,
      onPlaying: (p) => {
        this.playing = p;
        this.refresh();
      },
      onDelay: (ms) => this.update({ delayMs: ms }),
      onSkipped: () => this.update({ skipped: this.state.skipped + 1 }),
    });
  }

  getState(): DubState {
    return this.state;
  }

  get enabled(): boolean {
    return this.speaker !== null;
  }

  /** Turn dubbing on (or switch voice). Everything queued for an older voice is dropped. */
  enable(voice: string): void {
    if (this.speaker?.voice === voice && this.speakerStatus !== "failed") {
      this.speaker.warm();
      return;
    }
    this.teardownSpeaker();
    this.player.clear();
    this.lastSeq = 0;
    this.speakerStatus = "idle";
    this.speakerError = null;
    this.update({ ...INITIAL_DUB_STATE, status: "listening" });
    this.speaker = new FluxSpeaker({
      voice,
      // Connected and ready before the first phrase, so it isn't delayed by the handshake.
      keepWarm: true,
      getToken: this.opts.getToken,
      baseUrl: this.opts.speakBaseUrl,
      WebSocketImpl: this.opts.WebSocketImpl,
      onAudio: (seq, pcm) => this.player.push(seq, pcm),
      onTurnEnd: (seq) => this.player.end(seq),
      onStatus: (status, error) => {
        this.speakerStatus = status;
        this.speakerError = error;
        if (status === "failed") this.player.clear();
        this.refresh();
      },
    });
    this.refresh();
    this.speaker.warm();
  }

  /** Turn dubbing off: stop speech now and cancel pending synthesis. */
  disable(): void {
    this.teardownSpeaker();
    this.player.clear();
    this.translating = false;
    this.playing = false;
    this.lastSeq = 0;
    this.speakerStatus = "idle";
    this.speakerError = null;
    this.update({ ...INITIAL_DUB_STATE });
  }

  /** A translated phrase. Repeats (same or older `seq`) are ignored. */
  speak(segment: DubSegment): void {
    if (!this.speaker || segment.seq <= this.lastSeq) return;
    this.lastSeq = segment.seq;
    this.player.begin(segment.seq, segment.spokenAt);
    this.speaker.speak(segment);
  }

  /** The front half is translating a phrase (status only). */
  setTranslating(busy: boolean): void {
    this.translating = busy;
    this.refresh();
  }

  /** Drop queued and in-flight speech (seek, new video, new language). */
  clear(): void {
    this.speaker?.reset();
    this.player.clear();
    this.lastSeq = 0;
  }

  setPaused(paused: boolean): void {
    this.player.setPaused(paused);
  }

  async close(): Promise<void> {
    this.teardownSpeaker();
    await this.player.close();
  }

  private teardownSpeaker() {
    this.speaker?.close();
    this.speaker = null;
  }

  private refresh() {
    if (!this.speaker) return;
    const s = this.speakerStatus;
    if (s === "failed") return this.update({ status: "unavailable", error: this.speakerError });
    if (s === "reconnecting") return this.update({ status: "reconnecting", error: this.speakerError });
    if (this.playing) return this.update({ status: "playing", error: null });
    if (s === "connecting") return this.update({ status: "connecting", error: null });
    this.update({ status: this.translating ? "translating" : "listening", error: null });
  }

  private update(patch: Partial<DubState>) {
    const next = { ...this.state, ...patch };
    if (
      next.status === this.state.status &&
      next.error === this.state.error &&
      next.delayMs === this.state.delayMs &&
      next.skipped === this.state.skipped
    ) {
      return;
    }
    this.state = next;
    this.opts.onState?.(next);
  }
}
/**
 * Playback queue for dubbed speech (Web Audio).
 *
 * PCM chunks are scheduled back to back on one clock, so phrases play in order and never
 * overlap. A phrase whose first word would start too long after the original was spoken is
 * skipped, which keeps a livestream's dub close to live instead of replaying an ever-older
 * backlog. Nothing is stored: chunks are dropped as soon as they've played.
 */
import { DUB_SAMPLE_RATE } from "./flux-tts";

/** The parts of AudioContext the player uses (a fake in tests). */
export interface DubAudioContext {
  readonly currentTime: number;
  readonly destination: AudioNode;
  readonly state: AudioContextState;
  createGain(): GainNode;
  createBuffer(channels: number, length: number, sampleRate: number): AudioBuffer;
  createBufferSource(): AudioBufferSourceNode;
  suspend(): Promise<void>;
  resume(): Promise<void>;
  close(): Promise<void>;
}

export interface DubPlayerOptions {
  sampleRate?: number;
  /** Skip a phrase that would start more than this long after it was spoken. */
  maxLagMs?: number;
  /** Small scheduling lead so the first chunk isn't clipped. */
  leadSeconds?: number;
  createContext?: () => DubAudioContext;
  now?: () => number;
  /** Dubbed audio started (true) or ran out (false). */
  onPlaying?: (playing: boolean) => void;
  /** Delay of the phrase that just started, in ms (see DubState.delayMs). */
  onDelay?: (ms: number) => void;
  onSkipped?: () => void;
}

interface Phrase {
  spokenAt: number;
  /** Paused time already counted when the phrase was registered. */
  pausedBase: number;
  state: "waiting" | "playing" | "skipped";
}

export class DubPlayer {
  private ctx: DubAudioContext | null = null;
  private gain: GainNode | null = null;
  private volume = 1;
  private nextTime = 0;
  private phrases = new Map<number, Phrase>();
  private sources = new Set<AudioBufferSourceNode>();
  private paused = false;
  private pausedSince = 0;
  private pausedTotal = 0;
  private playing = false;
  private readonly sampleRate: number;
  private readonly maxLagMs: number;
  private readonly lead: number;
  private readonly now: () => number;

  constructor(private readonly opts: DubPlayerOptions = {}) {
    this.sampleRate = opts.sampleRate ?? DUB_SAMPLE_RATE;
    this.maxLagMs = opts.maxLagMs ?? 8000;
    this.lead = opts.leadSeconds ?? 0.05;
    this.now = opts.now ?? Date.now;
  }

  private context(): DubAudioContext {
    if (!this.ctx) {
      const ctx = this.opts.createContext?.() ?? (new AudioContext({ latencyHint: "interactive" }) as DubAudioContext);
      const gain = ctx.createGain();
      gain.gain.value = this.volume;
      gain.connect(ctx.destination);
      this.ctx = ctx;
      this.gain = gain;
      if (this.paused) void ctx.suspend().catch(() => undefined);
      else if (ctx.state === "suspended") void ctx.resume().catch(() => undefined);
    }
    return this.ctx;
  }

  /** Register a phrase before its audio arrives. */
  begin(seq: number, spokenAt: number): void {
    if (!this.phrases.has(seq)) this.phrases.set(seq, { spokenAt, pausedBase: this.pausedMs(), state: "waiting" });
  }

  /** Audio for a phrase (PCM16 mono). Unknown phrases are ignored (they were cleared). */
  push(seq: number, pcm: Int16Array): void {
    const phrase = this.phrases.get(seq);
    if (!phrase || phrase.state === "skipped" || pcm.length === 0) return;
    const ctx = this.context();
    const start = Math.max(ctx.currentTime + this.lead, this.nextTime);

    if (phrase.state === "waiting") {
      const age = this.now() - phrase.spokenAt - (this.pausedMs() - phrase.pausedBase);
      const delay = Math.round(age + (start - ctx.currentTime) * 1000);
      if (delay > this.maxLagMs) {
        phrase.state = "skipped";
        this.opts.onSkipped?.();
        return;
      }
      phrase.state = "playing";
      this.opts.onDelay?.(delay);
    }

    const buffer = ctx.createBuffer(1, pcm.length, this.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < pcm.length; i++) data[i] = pcm[i]! / 0x8000;
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(this.gain!);
    source.onended = () => {
      this.sources.delete(source);
      try {
        source.disconnect();
      } catch {
        /* already disconnected */
      }
      if (this.sources.size === 0) this.setPlaying(false);
    };
    this.sources.add(source);
    source.start(start);
    this.nextTime = start + pcm.length / this.sampleRate;
    this.setPlaying(true);
  }

  /** All audio for a phrase arrived; forget it once nothing more can come. */
  end(seq: number): void {
    this.phrases.delete(seq);
  }

  /** Stop and drop everything queued (seek, new language, dubbing off). */
  clear(): void {
    this.phrases.clear();
    for (const s of this.sources) {
      s.onended = null;
      try {
        s.stop();
        s.disconnect();
      } catch {
        /* not started or already stopped */
      }
    }
    this.sources.clear();
    this.nextTime = 0;
    this.setPlaying(false);
  }

  setVolume(volume: number): void {
    this.volume = Math.min(1, Math.max(0, volume));
    if (this.gain) this.gain.gain.value = this.volume;
  }

  /** Follow the source video: a paused video pauses the dub where it is. */
  setPaused(paused: boolean): void {
    if (paused === this.paused) return;
    this.paused = paused;
    if (paused) this.pausedSince = this.now();
    else this.pausedTotal += this.now() - this.pausedSince;
    if (!this.ctx) return;
    void (paused ? this.ctx.suspend() : this.ctx.resume()).catch(() => undefined);
  }

  /** Seconds of dubbed audio scheduled but not yet played. */
  get backlogSeconds(): number {
    return this.ctx ? Math.max(0, this.nextTime - this.ctx.currentTime) : 0;
  }

  async close(): Promise<void> {
    this.clear();
    const ctx = this.ctx;
    this.ctx = null;
    this.gain = null;
    await ctx?.close().catch(() => undefined);
  }

  private pausedMs() {
    return this.pausedTotal + (this.paused ? this.now() - this.pausedSince : 0);
  }

  private setPlaying(playing: boolean) {
    if (playing === this.playing) return;
    this.playing = playing;
    this.opts.onPlaying?.(playing);
  }
}

/**
 * Deepgram Flux TTS over the streaming `/v2/speak` WebSocket.
 *
 * One persistent socket per voice: each phrase is one turn (`Speak` + `Flush`), and raw
 * linear16 audio streams back as binary frames while the turn is synthesized. The server
 * handles turns in order, so audio frames map to phrases first-in, first-out using its
 * `SpeechStarted` / `SpeechMetadata` markers.
 *
 * Auth is the same as speech-to-text: browsers can't set headers on a WebSocket, so the
 * credential goes in the subprotocol (`["bearer", jwt]` or `["token", userKey]`).
 */
import type { DeepgramCredential } from "../types";
import type { DubSegment } from "./types";

export const DEEPGRAM_SPEAK_V2_URL = "wss://api.deepgram.com/v2/speak";
export const DUB_SAMPLE_RATE = 24000;

export function buildSpeakUrl(voice: string, base = DEEPGRAM_SPEAK_V2_URL, sampleRate = DUB_SAMPLE_RATE): string {
  const p = new URLSearchParams({ model: voice, encoding: "linear16", sample_rate: String(sampleRate) });
  return `${base}?${p.toString()}`;
}

export type SpeakerStatus = "idle" | "connecting" | "open" | "reconnecting" | "failed";

export interface FluxSpeakerOptions {
  voice: string;
  /** Called for every (re)connect, like the transcription session's `getToken`. */
  getToken: () => Promise<string | DeepgramCredential>;
  /** PCM16 mono audio for a phrase, in order. */
  onAudio: (seq: number, pcm: Int16Array) => void;
  /** All audio for a phrase has arrived. */
  onTurnEnd?: (seq: number) => void;
  onStatus?: (status: SpeakerStatus, error: string | null) => void;
  baseUrl?: string;
  sampleRate?: number;
  maxReconnectAttempts?: number;
  /** Close the socket after this long without phrases (the server closes idle ones at 60 s). */
  idleCloseMs?: number;
  /**
