        pipeline.start();
        setEnabled(true);
      } else {
        pipeline.stop();
        post({ type: "disable" });
        setEnabled(false);
      }
    },
    [pipeline, post, settings.language, spokenLanguage],
  );

  return { settings, setSettings, enabled: enabled && capturing, setDubbing, issue, state: snap.dub };
}
