</div>
<script>
const $ = (id) => document.getElementById(id);
const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const seg = (t, a, b) => clamp((t - a) / (b - a));
const ease = (p) => (p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2);
const out = (p) => 1 - Math.pow(1 - p, 3);
const back = (p) => { const c = 1.6; return 1 + (c + 1) * Math.pow(p - 1, 3) + c * Math.pow(p - 1, 2); };
const lerp = (a, b, p) => a + (b - a) * p;
const WPS = 3.4;

const CAPS = [
  [6.6, "Welcome back to the kitchen."],
  [8.4, "Today we're baking our very first loaf of sourdough."],
  [10.9, "Start with a starter that's bubbly and smells a little sweet."],
  [13.6, "Mix the flour and water, then let it rest."],
  [15.7, "That rest is called the autolyse."],
  [17.5, "It makes the dough easier to shape."],
  [22.5, "Ahora añade la sal y un chorrito de agua."],
  [24.2, "Amasa hasta que la masa quede suave."],
];
const HEADS = [
  [3.5, 8.3, "Press Start on any tab that plays audio."],
  [8.3, 13.0, "Captions appear as people speak."],
  [13.0, 20.2, "Every word lands in a transcript you can search."],
  [20.2, 25.4, "Switch captions to another language."],
];
const shown = (text, start, t) => { const w = text.split(" "); return w.slice(0, Math.min(w.length, Math.floor((t - start) * WPS) + 1)).join(" "); };
const dur = (text) => text.split(" ").length / WPS;
const stamp = (start) => { const s = Math.round(start - 6.6 + 2); return `0:${String(s).padStart(2, "0")}`; };
const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");

function typed(text, t, a, cps = 30) { return text.slice(0, clamp(Math.floor((t - a) * cps), 0, text.length)); }

window.render = (t) => {
  // ---------- Brand (intro 0–3.4, outro 25.6–30)
  const intro = t < 10;
  const bIn = intro ? 1 : out(seg(t, 25.7, 26.4));
  const bOut = intro ? 1 - ease(seg(t, 3.0, 3.5)) : 1;
  const brand = $("brand");
  brand.style.opacity = intro ? bOut : bIn;
  brand.style.display = (intro ? bOut > 0 : bIn > 0) ? "flex" : "none";
  const ip = intro ? back(seg(t, 0.15, 0.8)) : back(seg(t, 25.7, 26.3));
  document.querySelector(".icon").style.transform = `scale(${Math.max(0, ip)}) rotate(${(1 - ip) * -10}deg)`;
  const wp = intro ? out(seg(t, 0.55, 1.2)) : out(seg(t, 25.95, 26.6));
  $("word").style.opacity = wp; $("word").style.transform = `translateX(${(1 - wp) * -40}px)`;
  const barA = intro ? out(seg(t, 0.6, 1.1)) : out(seg(t, 26.0, 26.5));
  $("b1").style.width = 116 * barA + "px"; $("b2").style.width = 80 * out(clamp(barA * 1.3 - 0.3)) + "px";
  const tagStart = intro ? 1.1 : 26.6;
  const tag = "Live AI captions for any tab that plays audio.";
  $("tag").style.opacity = out(seg(t, tagStart - 0.15, tagStart + 0.15));
  $("tag").textContent = t >= tagStart ? shown(tag, tagStart, tagStart + (t - tagStart) * 1.6) : " ";
  $("store").style.display = intro ? "none" : "flex";
  $("store").style.opacity = out(seg(t, 27.4, 27.9)); $("store").style.transform = `translateY(${(1 - out(seg(t, 27.4, 27.9))) * 16}px)`;
  $("brand").style.transform = intro ? `scale(${1 + 0.05 * ease(seg(t, 3.0, 3.5))})` : `scale(${0.97 + 0.03 * out(seg(t, 25.7, 26.6))})`;

  // ---------- Headline
  let h = HEADS.find(([a, b]) => t >= a && t < b);
  const head = $("head");
  if (h) {
    const [a, b, text] = h;
    const p = out(seg(t, a, a + 0.45)) * (1 - ease(seg(t, b - 0.3, b)));
    head.textContent = text; head.style.opacity = p; head.style.transform = `translateY(${(1 - out(seg(t, a, a + 0.45))) * 18}px)`;
  } else head.style.opacity = 0;

  // ---------- Window
  const win = $("win");
  const wIn = out(seg(t, 3.3, 4.0)), wOut = ease(seg(t, 25.1, 25.7));
  win.style.display = wIn > 0 && wOut < 1 ? "block" : "none";
  win.style.opacity = wIn * (1 - wOut);
  win.style.transform = `translateY(${(1 - wIn) * 60}px) scale(${1 - wOut * 0.04})`;

  // Video and panel layout
  const pp = ease(seg(t, 12.9, 13.7));
  const vx = lerp(230, 30, pp);
  $("video").style.left = vx + "px"; $("vt").style.left = vx + "px";
  $("panel").style.transform = `translateX(${(1 - pp) * 420}px)`;
  const kb = 1 + 0.06 * seg(t, 3, 26);
  $("scene").style.transform = `scale(${kb}) translate(${-seg(t, 3, 26) * 20}px, 0)`;
  $("prog").style.width = (8 + 30 * seg(t, 4, 26)) + "%";

  // Popup + cursor
  const popIn = out(seg(t, 4.75, 5.05)), popOut = ease(seg(t, 6.1, 6.4));
  const pop = $("pop");
  pop.style.display = popIn > 0 && popOut < 1 ? "block" : "none";
  pop.style.opacity = popIn * (1 - popOut);
  pop.style.transform = `translateY(${(1 - popIn) * -10}px)`;
  const started = t >= 5.75;
  $("btn").textContent = started ? "Stop captions" : "Start captions";
  $("btn").style.background = started ? "#2a2a33" : "#f5b83d";
  $("btn").style.color = started ? "#efeff5" : "#1d1404";
  $("btn").style.transform = `scale(${t > 5.6 && t < 5.8 ? 0.96 : 1})`;
  // cursor path in stage coords: window at (210,210)
  const P = [[960, 760, 3.8], [1662, 237, 4.55], [1662, 237, 5.15], [1540, 380, 5.55], [1540, 380, 6.1], [1300, 640, 6.7]];
  let cx = P[0][0], cy = P[0][1];
  for (let i = 1; i < P.length; i++) { const [x0, y0, t0] = P[i - 1], [x1, y1, t1] = P[i]; if (t >= t0) { const q = ease(seg(t, t0, t1)); cx = lerp(x0, x1, q); cy = lerp(y0, y1, q); } }
  const cur = $("cursor");
  const cv = out(seg(t, 3.7, 4.0)) * (1 - seg(t, 6.4, 6.8));
  cur.style.opacity = cv; cur.style.display = cv > 0 ? "block" : "none";
  cur.style.left = cx - 4 + "px"; cur.style.top = cy - 2 + "px";
  const clicks = [4.6, 5.62];
  const ck = clicks.map((c) => seg(t, c, c + 0.45)).find((v) => v > 0 && v < 1);
  $("ring").style.opacity = ck ? 1 - ck : 0; $("ring").style.transform = `scale(${ck ? 0.5 + ck : 0})`;
  $("tb").style.transform = `scale(${t > 4.55 && t < 4.75 ? 0.88 : 1})`;

  // Captions on the video
  const cap = $("cap");
  const cur1 = [...CAPS].reverse().find(([s]) => t >= s);
  if (cur1 && t < cur1[0] + dur(cur1[1]) + 1.4 && t < 25.3) {
    cap.style.display = "block";
    cap.innerHTML = `<div class="live"><i></i>Live</div>${esc(shown(cur1[1], cur1[0], t))}`;
    const fi = out(seg(t, CAPS[0][0] - 0.2, CAPS[0][0] + 0.1));
    cap.style.opacity = cur1 === CAPS[0] ? fi : 1;
  } else cap.style.display = "none";

  // Panel: tab view vs settings
  const inSettings = t >= 20.5 && t < 22.25;
  $("tT").className = inSettings ? "" : "on"; $("tS").className = inSettings ? "on" : "";
  $("tview").style.display = inSettings ? "none" : "block";
  $("settings").style.display = inSettings ? "block" : "none";
  const picked = t >= 21.75;
  $("selv").innerHTML = `${picked ? "Español" : "Same as spoken"}<span>▾</span>`;
  $("selv").className = "sel" + (t >= 20.9 && t < 21.8 ? " focus" : "");
  $("snote").textContent = picked ? "English → Español is ready. Captions switch right away." : "";
  const menuOpen = t >= 21.0 && t < 21.75;
  const menu = $("menu"); menu.style.display = menuOpen ? "block" : "none";
  const hi = t >= 21.35 ? 2 : 0;
  menu.innerHTML = ["Same as spoken", "English", "Español", "Français", "Deutsch", "日本語"].map((o, i) => `<div class="${i === hi ? "hi" : ""}">${o}</div>`).join("");

  // Search
  const q = t >= 18.2 && t < 20.3 ? typed("autolyse", t, 18.25, 14) : "";
  $("search").innerHTML = q ? `${q}${Math.floor(t * 2.5) % 2 ? '<span class="caret"></span>' : ""}` : `<span class="ph2">Search transcript</span>`;
  const qOn = q.length >= 4;
  // Transcript list
  const items = CAPS.filter(([s]) => t >= s).map(([s, text]) => {
    let body = esc(shown(text, s, t));
    const match = qOn && body.toLowerCase().includes(q.toLowerCase());
    if (match) body = body.replace(new RegExp(q, "i"), (m) => `<mark>${m}</mark>`);
    const op = qOn && !match ? 0.3 : 1;
    return `<div class="it" style="opacity:${op * out(seg(t, s, s + 0.3))}"><span class="ts">${stamp(s)}</span><span class="tx">${body}</span></div>`;
  });
  $("inner").innerHTML = items.join("");
  const lh = $("list").clientHeight, ih = $("inner").scrollHeight;
  $("inner").style.transform = `translateY(${Math.min(0, lh - ih - 10)}px)`;
};
window.render(0);
</script>
</body></html>

